(324858,36096,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, ich hab die Regel vom Chef gehört: Die Umzugsleute ... den Laster bis Mittag vollladen.'::text,'müssen'::text,'müssen'::text,'sollten'::text,'Bestie, ich hab die Regel vom Chef gehört: Die Umzugsleute müssen den Laster bis Mittag vollladen.'::text),
(324862,36096,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подружко, я чула правило боса: вантажники ... заповнити вантажівку до обіду.'::text,'мають'::text,'мусять'::text,'мали б'::text,'Подружко, я чула правило боса: вантажники мають заповнити вантажівку до обіду.'::text),
(324861,36096,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, me enteré de la regla del jefe: los de la mudanza ... llenar el camión antes del mediodía.'::text,'tienen que'::text,'deben'::text,'deberían'::text,'Amiga, me enteré de la regla del jefe: los de la mudanza tienen que llenar el camión antes del mediodía.'::text),
(324860,36096,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma chérie, j''ai entendu la règle du boss : les déménageurs ... remplir le camion avant midi.'::text,'doivent'::text,'doivent'::text,'devraient'::text,'Ma chérie, j''ai entendu la règle du boss : les déménageurs doivent remplir le camion avant midi.'::text),
(324863,36096,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, patronun kuralını duydum: taşımacılar kamyonu öğlene kadar ...'::text,'doldurmak zorunda'::text,'doldurmalı'::text,'doldurmalı'::text,'Kanka, patronun kuralını duydum: taşımacılar kamyonu öğlene kadar doldurmak zorunda.'::text),
(324864,36096,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, hallottam a főnök szabályát: a költöztetőknek délre meg ... tölteniük a teherautót.'::text,'kell'::text,'kell'::text,'kellene'::text,'Csajszi, hallottam a főnök szabályát: a költöztetőknek délre meg kell tölteniük a teherautót.'::text),
(316830,35204,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hunderte Leute ... auf den Sitzen um sie herum.'::text,'sitzen'::text,'sitzt'::text,'sitzend'::text,'Hunderte Leute sitzen auf den Sitzen um sie herum.'::text),
(316834,35204,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сотні людей ... на місцях навколо неї.'::text,'сидять'::text,'сидить'::text,'сидячи'::text,'Сотні людей сидять на місцях навколо неї.'::text),
(316833,35204,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cientos de personas ... en los asientos a su alrededor.'::text,'se sientan'::text,'se sienta'::text,'sentándose'::text,'Cientos de personas se sientan en los asientos a su alrededor.'::text),
(316832,35204,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Des centaines de personnes ... sur les sièges autour d''elle.'::text,'s''assoient'::text,'s''assoit'::text,'s''asseyant'::text,'Des centaines de personnes s''assoient sur les sièges autour d''elle.'::text),
(316835,35204,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yüzlerce kişi onun etrafındaki koltuklarda ...'::text,'otururlar'::text,'oturur'::text,'oturarak'::text,'Yüzlerce kişi onun etrafındaki koltuklarda otururlar.'::text),
(316836,35204,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Emberek százai ... a körülötte lévő székeken.'::text,'ülnek'::text,'ül'::text,'ülő'::text,'Emberek százai ülnek a körülötte lévő székeken.'::text),
(316839,35205,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Saal ist groß. Tausende Leute ... hier sitzen.'::text,'können'::text,'sind'::text,'können'::text,'Der Saal ist groß. Tausende Leute können hier sitzen.'::text),
(316843,35205,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зала велика. Тисячі людей ... тут сидіти.'::text,'можуть'::text,'є'::text,'можуть'::text,'Зала велика. Тисячі людей можуть тут сидіти.'::text),
(316842,35205,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La sala es grande. Miles de personas ... sentarse aquí.'::text,'pueden'::text,'están'::text,'pueden'::text,'La sala es grande. Miles de personas pueden sentarse aquí.'::text),
(316841,35205,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La salle est grande. Des milliers de personnes ... s''asseoir ici.'::text,'peuvent'::text,'sont'::text,'peuvent'::text,'La salle est grande. Des milliers de personnes peuvent s''asseoir ici.'::text),
(316844,35205,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Salon büyük. Binlerce kişi burada ...'::text,'oturabilir'::text,NULL::text,'oturabilir'::text,'Salon büyük. Binlerce kişi burada oturabilir.'::text),
(316845,35205,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A terem nagy. Emberek ezrei ... itt.'::text,'ülhetnek'::text,'vannak'::text,'ülhetnek'::text,'A terem nagy. Emberek ezrei ülhetnek itt.'::text),
(316857,35207,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... sich in einem leeren Saal hin und atmete aus.'::text,'setzte'::text,'setzt'::text,'setzen'::text,'Sie setzte sich in einem leeren Saal hin und atmete aus.'::text),
(316861,35207,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... в порожній залі й видихнула.'::text,'сіла'::text,'сідає'::text,'сісти'::text,'Вона сіла в порожній залі й видихнула.'::text),
(316860,35207,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella ... en una sala vacía y soltó el aire.'::text,'se sentó'::text,'se sienta'::text,'sentarse'::text,'Ella se sentó en una sala vacía y soltó el aire.'::text),
(316859,35207,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... dans une salle vide et a expiré.'::text,'s''est assise'::text,'s''assoit'::text,'s''asseoir'::text,'Elle s''est assise dans une salle vide et a expiré.'::text),
(316862,35207,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Boş bir salonda ... ve derin bir nefes verdi.'::text,'oturdu'::text,'oturur'::text,'oturmak'::text,'Boş bir salonda oturdu ve derin bir nefes verdi.'::text),
(316863,35207,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... egy üres teremben, és kifújta a levegőt.'::text,'Leült'::text,'Leül'::text,'Leülni'::text,'Leült egy üres teremben, és kifújta a levegőt.'::text),
(316866,35208,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sonst sitzt sie zu Hause, aber gestern ... sie in einem riesigen Saal.'::text,'saß'::text,'sitzt'::text,NULL::text,'Sonst sitzt sie zu Hause, aber gestern saß sie in einem riesigen Saal.'::text),
(316870,35208,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай вона сидить удома, але вчора ... у величезній залі.'::text,'сиділа'::text,'сидить'::text,NULL::text,'Зазвичай вона сидить удома, але вчора сиділа у величезній залі.'::text),
(316869,35208,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente se sienta en casa, pero ayer ... en una sala enorme.'::text,'se sentó'::text,'se sienta'::text,NULL::text,'Normalmente se sienta en casa, pero ayer se sentó en una sala enorme.'::text),
(316868,35208,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude elle s''assoit chez elle, mais hier elle ... dans une immense salle.'::text,'s''est assise'::text,'s''assoit'::text,NULL::text,'D''habitude elle s''assoit chez elle, mais hier elle s''est assise dans une immense salle.'::text),
(316871,35208,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde evde oturur ama dün kocaman bir salonda ...'::text,'oturdu'::text,'oturur'::text,NULL::text,'Genelde evde oturur ama dün kocaman bir salonda oturdu.'::text),
(316872,35208,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában otthon ül, de tegnap egy hatalmas teremben ...'::text,'ült'::text,'ül'::text,NULL::text,'Általában otthon ül, de tegnap egy hatalmas teremben ült.'::text),
(316875,35209,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also ich hab gehört, der ganze Saal ... gerade hinter ihr.'::text,'sitzt'::text,'sitzt'::text,'sitzt'::text,'Okay, also ich hab gehört, der ganze Saal sitzt gerade hinter ihr.'::text),
(316879,35209,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, я чула, що вся зала ... зараз позаду неї.'::text,'сидить'::text,'сидить'::text,'сидить'::text,'Коротше, я чула, що вся зала сидить зараз позаду неї.'::text),
(316878,35209,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, me han dicho que toda la sala ... detrás de ella ahora mismo.'::text,'está sentada'::text,'se sienta'::text,'está sentada'::text,'Vale, me han dicho que toda la sala está sentada detrás de ella ahora mismo.'::text),
(316877,35209,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon, j''ai entendu que toute la salle ... derrière elle en ce moment.'::text,'est assise'::text,'s''assoit'::text,'est assise'::text,'Bon, j''ai entendu que toute la salle est assise derrière elle en ce moment.'::text),
(316880,35209,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam bak, duydum ki bütün salon şu an onun arkasında ...'::text,'oturuyor'::text,'oturur'::text,'oturuyor'::text,'Tamam bak, duydum ki bütün salon şu an onun arkasında oturuyor.'::text),
(316881,35209,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, figyi, azt hallottam, hogy az egész terem épp most mögötte ...'::text,'ül'::text,'ül'::text,'ül'::text,'Oké, figyi, azt hallottam, hogy az egész terem épp most mögötte ül.'::text),
(316893,35211,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Erst sitzt du allein, ... bald ist der Saal voll. Ikonisch.'::text,'aber'::text,'weil'::text,'also'::text,'Erst sitzt du allein, aber bald ist der Saal voll. Ikonisch.'::text),
(316897,35211,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Спершу ти сидиш сама, ... скоро зала повна. Легенда.'::text,'але'::text,'бо'::text,'тому'::text,'Спершу ти сидиш сама, але скоро зала повна. Легенда.'::text),
(316896,35211,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Al principio te sientas sola, ... pronto la sala está llena. Icónico.'::text,'pero'::text,'porque'::text,'así que'::text,'Al principio te sientas sola, pero pronto la sala está llena. Icónico.'::text),
(316895,35211,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Au début tu es assise seule, ... bientôt la salle est pleine. Iconique.'::text,'mais'::text,'parce que'::text,'donc'::text,'Au début tu es assise seule, mais bientôt la salle est pleine. Iconique.'::text),
(316898,35211,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Önce tek başına oturuyorsun ... kısa sürede salon doluyor. Efsane.'::text,'ama'::text,'çünkü'::text,'bu yüzden'::text,'Önce tek başına oturuyorsun ama kısa sürede salon doluyor. Efsane.'::text),
(316899,35211,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Először egyedül ülsz, ... hamar megtelik a terem. Ikonikus.'::text,'de'::text,'mert'::text,'ezért'::text,'Először egyedül ülsz, de hamar megtelik a terem. Ikonikus.'::text),
(312915,34769,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... die Türen das Tal, weil sie offen sind.'::text,'enthüllen'::text,'enthüllen'::text,NULL::text,'Gerade enthüllen die Türen das Tal, weil sie offen sind.'::text),
(312919,34769,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Саме зараз двері ... долину, бо вони відчинені.'::text,'відкривають'::text,'відкривають'::text,NULL::text,'Саме зараз двері відкривають долину, бо вони відчинені.'::text),
(312918,34769,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo las puertas ... el valle porque están abiertas.'::text,'están revelando'::text,'revelan'::text,NULL::text,'Ahora mismo las puertas están revelando el valle porque están abiertas.'::text),
(312917,34769,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, les portes ... la vallée parce qu''elles sont ouvertes.'::text,'sont en train de révéler'::text,'révèlent'::text,NULL::text,'En ce moment, les portes sont en train de révéler la vallée parce qu''elles sont ouvertes.'::text),
(312920,34769,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu an kapılar açık olduğu için vadiyi ...'::text,'ortaya çıkarıyor'::text,'ortaya çıkarır'::text,NULL::text,'Şu an kapılar açık olduğu için vadiyi ortaya çıkarıyor.'::text),
(312921,34769,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ajtók épp most ... a völgyet, mert nyitva vannak.'::text,'felfedik'::text,'felfedik'::text,NULL::text,'Az ajtók épp most felfedik a völgyet, mert nyitva vannak.'::text),
(312924,34770,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, ein Schubs und du ... hier die beste Aussicht enthüllen.'::text,'wirst'::text,'enthüllst'::text,'enthülltest'::text,'Ehrlich, ein Schubs und du wirst hier die beste Aussicht enthüllen.'::text),
(312928,34770,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, один поштовх — і ти ... найкращий краєвид тут.'::text,'відкриєш'::text,'відкриваєш'::text,'відкрила'::text,'Чесно, один поштовх — і ти відкриєш найкращий краєвид тут.'::text),
(312927,34770,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, un empujón y ... la mejor vista de aquí.'::text,'revelarás'::text,'revelas'::text,'revelaste'::text,'La verdad, un empujón y revelarás la mejor vista de aquí.'::text),
(312926,34770,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, une poussée et tu ... la plus belle vue d''ici.'::text,'révéleras'::text,'révèles'::text,'as révélé'::text,'Franchement, une poussée et tu révéleras la plus belle vue d''ici.'::text),
(312929,34770,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, bir itiş ve buradaki en güzel manzarayı ...'::text,'ortaya çıkaracaksın'::text,'ortaya çıkarırsın'::text,'ortaya çıkardın'::text,'Açıkçası, bir itiş ve buradaki en güzel manzarayı ortaya çıkaracaksın.'::text),
(312930,34770,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, egy lökés, és ... az itteni legszebb kilátást.'::text,'fel fogod fedni'::text,'felfeded'::text,'felfedted'::text,'Őszintén, egy lökés, és fel fogod fedni az itteni legszebb kilátást.'::text),
(312933,34771,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dein Plan ist smooth: Du ... das Tal mit einem großen Schubs enthüllen.'::text,'wirst'::text,'wirst'::text,'wirst'::text,'Dein Plan ist smooth: Du wirst das Tal mit einem großen Schubs enthüllen.'::text),
(312937,34771,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Твій план — вогонь: ти ... долину одним сильним поштовхом.'::text,'збираєшся відкрити'::text,'відкриєш'::text,'збираєшся відкрити'::text,'Твій план — вогонь: ти збираєшся відкрити долину одним сильним поштовхом.'::text),
(312936,34771,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu plan es fino: ... el valle de un gran empujón.'::text,'vas a revelar'::text,'revelarás'::text,'vas a revelar'::text,'Tu plan es fino: vas a revelar el valle de un gran empujón.'::text),
(312935,34771,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ton plan est smooth : tu ... la vallée d''une seule grande poussée.'::text,'vas révéler'::text,'révéleras'::text,'vas révéler'::text,'Ton plan est smooth : tu vas révéler la vallée d''une seule grande poussée.'::text),
(312938,34771,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Planın çok şık: vadiyi tek bir büyük itişle ...'::text,'ortaya çıkaracaksın'::text,'ortaya çıkaracaksın'::text,'ortaya çıkaracaksın'::text,'Planın çok şık: vadiyi tek bir büyük itişle ortaya çıkaracaksın.'::text),
(312939,34771,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Profi a terved: egyetlen nagy lökéssel ... a völgyet.'::text,'fel fogod fedni'::text,'fel fogod fedni'::text,'fel fogod fedni'::text,'Profi a terved: egyetlen nagy lökéssel fel fogod fedni a völgyet.'::text),
(312942,34772,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, du bist schon an den Türen. Du ... jetzt die Aussicht enthüllen.'::text,'wirst'::text,'wirst'::text,NULL::text,'Ehrlich, du bist schon an den Türen. Du wirst jetzt die Aussicht enthüllen.'::text),
(312946,34772,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ти вже біля дверей. Ти ... краєвид зараз.'::text,'збираєшся відкрити'::text,'відкриєш'::text,NULL::text,'Чесно, ти вже біля дверей. Ти збираєшся відкрити краєвид зараз.'::text),
(312945,34772,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La verdad, ya estás en las puertas. Ahora ... la vista.'::text,'vas a revelar'::text,'revelarás'::text,NULL::text,'La verdad, ya estás en las puertas. Ahora vas a revelar la vista.'::text),
(312944,34772,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Franchement, tu es déjà aux portes. Tu ... la vue maintenant.'::text,'vas révéler'::text,'révéleras'::text,NULL::text,'Franchement, tu es déjà aux portes. Tu vas révéler la vue maintenant.'::text),
(312947,34772,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Açıkçası, zaten kapıdasın. Şimdi manzarayı ...'::text,'ortaya çıkaracaksın'::text,'ortaya çıkaracaksın'::text,NULL::text,'Açıkçası, zaten kapıdasın. Şimdi manzarayı ortaya çıkaracaksın.'::text),
(312948,34772,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Őszintén, már az ajtóknál vagy. Most ... a kilátást.'::text,'fel fogod fedni'::text,'fel fogod fedni'::text,NULL::text,'Őszintén, már az ajtóknál vagy. Most fel fogod fedni a kilátást.'::text),
(312951,34773,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie sagt sich: Ich ... heute diese Aussicht enthüllen.'::text,'muss'::text,'muss'::text,'sollte'::text,'Sie sagt sich: Ich muss heute diese Aussicht enthüllen.'::text),
(312955,34773,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона каже собі: я ... сьогодні відкрити той краєвид.'::text,'мушу'::text,'маю'::text,'мала б'::text,'Вона каже собі: я мушу сьогодні відкрити той краєвид.'::text),
(312954,34773,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ella se dice: ... revelar esa vista hoy.'::text,'debo'::text,'tengo que'::text,'debería'::text,'Ella se dice: debo revelar esa vista hoy.'::text),
(312953,34773,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle se dit : je ... révéler cette vue aujourd''hui.'::text,'dois'::text,'dois'::text,'devrais'::text,'Elle se dit : je dois révéler cette vue aujourd''hui.'::text),
(312956,34773,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kendine diyor ki: bugün o manzarayı ...'::text,'ortaya çıkarmalıyım'::text,'ortaya çıkarmak zorundayım'::text,'ortaya çıkarmalıyım'::text,'Kendine diyor ki: bugün o manzarayı ortaya çıkarmalıyım.'::text),
(312957,34773,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondja magának: ma fel ... fednem azt a kilátást.'::text,'kell'::text,'kell'::text,'kellene'::text,'Azt mondja magának: ma fel kell fednem azt a kilátást.'::text),
(312960,34774,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Um das Tal zu enthüllen, ... sie beide Türen öffnen.'::text,'sollte'::text,'sollte'::text,'sollte'::text,'Um das Tal zu enthüllen, sollte sie beide Türen öffnen.'::text),
(312964,34774,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Щоб відкрити долину, вона ... відчинити обидві двері.'::text,'мала б'::text,'мала б'::text,'мала б'::text,'Щоб відкрити долину, вона мала б відчинити обидві двері.'::text),
(312963,34774,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para revelar el valle, ... abrir las dos puertas.'::text,'debería'::text,'debería'::text,'debería'::text,'Para revelar el valle, debería abrir las dos puertas.'::text),
(312962,34774,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pour révéler la vallée, elle ... ouvrir les deux portes.'::text,'devrait'::text,'devrait'::text,'devrait'::text,'Pour révéler la vallée, elle devrait ouvrir les deux portes.'::text),
(312965,34774,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vadiyi ortaya çıkarmak için iki kapıyı da ...'::text,'açmalı'::text,'açmalı'::text,'açmalı'::text,'Vadiyi ortaya çıkarmak için iki kapıyı da açmalı.'::text),
(312966,34774,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hogy felfedje a völgyet, mindkét ajtót ki ... nyitnia.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Hogy felfedje a völgyet, mindkét ajtót ki kellene nyitnia.'::text),
(310107,34457,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keiner bewegt sich! Jeder ... in den Himmel!'::text,'zeigt'::text,'zeigen'::text,'zeigend'::text,'Keiner bewegt sich! Jeder zeigt in den Himmel!'::text),
(310111,34457,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніхто не рухається! Кожен ... на небо!'::text,'показує'::text,'показувати'::text,'показуючи'::text,'Ніхто не рухається! Кожен показує на небо!'::text),
(310110,34457,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Nadie se mueve! ¡Todo el mundo ... al cielo!'::text,'señala'::text,'señalar'::text,'señalando'::text,'¡Nadie se mueve! ¡Todo el mundo señala al cielo!'::text),
(310109,34457,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Personne ne bouge ! Tout le monde ... le ciel !'::text,'montre'::text,'montrer'::text,'montrant'::text,'Personne ne bouge ! Tout le monde montre le ciel !'::text),
(310112,34457,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kimse kıpırdamıyor! Herkes gökyüzünü ...!'::text,'gösterir'::text,'göstermek'::text,'göstererek'::text,'Kimse kıpırdamıyor! Herkes gökyüzünü gösterir!'::text),
(310113,34457,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Senki sem mozdul! Mindenki az égre ...!'::text,'mutat'::text,'mutatni'::text,'mutató'::text,'Senki sem mozdul! Mindenki az égre mutat!'::text),
(310125,34459,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... zeigen sie alle? Auf etwas Schreckliches am Himmel!'::text,'Worauf'::text,'Wer'::text,'Wo'::text,'Worauf zeigen sie alle? Auf etwas Schreckliches am Himmel!'::text),
(310129,34459,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... вони всі показують? На щось жахливе в небі!'::text,'На що'::text,'На кого'::text,'Куди'::text,'На що вони всі показують? На щось жахливе в небі!'::text),
(310128,34459,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... señalan todos? ¡Algo aterrador en el cielo!'::text,'Qué'::text,'Quién'::text,'Dónde'::text,'¿Qué señalan todos? ¡Algo aterrador en el cielo!'::text),
(310127,34459,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... montrent-ils tous ? Un truc terrifiant dans le ciel !'::text,'Que'::text,'Qui'::text,'Où'::text,'Que montrent-ils tous ? Un truc terrifiant dans le ciel !'::text),
(310130,34459,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hepsi ... gösteriyor? Gökyüzündeki korkunç bir şeyi!'::text,'neyi'::text,'kimi'::text,'nereyi'::text,'Hepsi neyi gösteriyor? Gökyüzündeki korkunç bir şeyi!'::text),
(310131,34459,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... mutatnak mind? Valami rémisztőre az égen!'::text,'Mire'::text,'Kire'::text,'Hová'::text,'Mire mutatnak mind? Valami rémisztőre az égen!'::text),
(310134,34460,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also angeblich ... eine Frau zuerst zum Himmel, und dann alle.'::text,'zeigte'::text,'zeigt'::text,'zeigend'::text,'Okay, also angeblich zeigte eine Frau zuerst zum Himmel, und dann alle.'::text),
(310138,34460,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коротше, кажуть, одна жінка першою ... на небо, а потім усі.'::text,'показала'::text,'показує'::text,'показуючи'::text,'Коротше, кажуть, одна жінка першою показала на небо, а потім усі.'::text),
(310137,34460,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues dicen que una mujer ... al cielo primero, y luego todos.'::text,'señaló'::text,'señala'::text,'señalando'::text,'Vale, pues dicen que una mujer señaló al cielo primero, y luego todos.'::text),
(310136,34460,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bon alors, apparemment une femme ... le ciel en premier, et ensuite tout le monde.'::text,'a montré'::text,'montre'::text,'montrant'::text,'Bon alors, apparemment une femme a montré le ciel en premier, et ensuite tout le monde.'::text),
(310139,34460,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam bak, duyduğuma göre gökyüzünü önce bir kadın ..., sonra da herkes.'::text,'gösterdi'::text,'gösterir'::text,'göstererek'::text,'Tamam bak, duyduğuma göre gökyüzünü önce bir kadın gösterdi, sonra da herkes.'::text),
(310140,34460,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval állítólag először egy nő ... az égre, aztán mindenki.'::text,'mutatott'::text,'mutat'::text,'mutató'::text,'Oké, szóval állítólag először egy nő mutatott az égre, aztán mindenki.'::text),
(310143,34461,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalerweise schauen die Leute auf ihre Handys, aber gestern ... Hunderte zum Himmel.'::text,'zeigten'::text,'zeigen'::text,NULL::text,'Normalerweise schauen die Leute auf ihre Handys, aber gestern zeigten Hunderte zum Himmel.'::text),
(310147,34461,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Люди зазвичай дивляться в телефони, але вчора сотні ... на небо.'::text,'показували'::text,'показують'::text,NULL::text,'Люди зазвичай дивляться в телефони, але вчора сотні показували на небо.'::text),
(310146,34461,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente la gente mira el móvil, pero ayer cientos ... al cielo.'::text,'señalaron'::text,'señalan'::text,NULL::text,'Normalmente la gente mira el móvil, pero ayer cientos señalaron al cielo.'::text),
(310145,34461,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude les gens regardent leur téléphone, mais hier des centaines ... le ciel.'::text,'ont montré'::text,'montrent'::text,NULL::text,'D''habitude les gens regardent leur téléphone, mais hier des centaines ont montré le ciel.'::text),
(310148,34461,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İnsanlar genelde telefonlarına bakar ama dün yüzlercesi gökyüzünü ...'::text,'gösterdi'::text,'gösterir'::text,NULL::text,'İnsanlar genelde telefonlarına bakar ama dün yüzlercesi gökyüzünü gösterdi.'::text),
(310149,34461,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az emberek általában a telefonjukat nézik, de tegnap százan ... az égre.'::text,'mutattak'::text,'mutatnak'::text,NULL::text,'Az emberek általában a telefonjukat nézik, de tegnap százan mutattak az égre.'::text),
(310152,34462,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Menge auf dem Platz ... jetzt hoch zum Himmel.'::text,'zeigt'::text,'zeigt'::text,'zeigt'::text,'Die Menge auf dem Platz zeigt jetzt hoch zum Himmel.'::text),
(310156,34462,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Натовп на площі зараз ... вгору на небо.'::text,'показує'::text,'показує'::text,'показує'::text,'Натовп на площі зараз показує вгору на небо.'::text),
(310155,34462,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La multitud de la plaza ... hacia el cielo ahora.'::text,'está señalando'::text,'señala'::text,'está señalando'::text,'La multitud de la plaza está señalando hacia el cielo ahora.'::text),
(310154,34462,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La foule sur la place ... le ciel maintenant.'::text,'est en train de montrer'::text,'montre'::text,'est en train de montrer'::text,'La foule sur la place est en train de montrer le ciel maintenant.'::text),
(310157,34462,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meydandaki kalabalık şimdi yukarıya, gökyüzünü ...'::text,'gösteriyor'::text,'gösterir'::text,'gösteriyor'::text,'Meydandaki kalabalık şimdi yukarıya, gökyüzünü gösteriyor.'::text),
(310158,34462,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A téren álló tömeg most felfelé az égre ...'::text,'mutat'::text,'mutat'::text,'mutat'::text,'A téren álló tömeg most felfelé az égre mutat.'::text),
(310161,34463,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Memo: Alle 300 Leute ... für das Foto auf dieselbe Stelle zeigen.'::text,'sollten'::text,'sollten'::text,'sollten'::text,'Memo: Alle 300 Leute sollten für das Foto auf dieselbe Stelle zeigen.'::text),
(310165,34463,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Службова записка: усі 300 людей ... показати на те саме місце для фото.'::text,'мали б'::text,'мали б'::text,'мали б'::text,'Службова записка: усі 300 людей мали б показати на те саме місце для фото.'::text),
(310164,34463,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Memorándum: las 300 personas ... señalar el mismo punto para la foto.'::text,'deberían'::text,'deberían'::text,'deberían'::text,'Memorándum: las 300 personas deberían señalar el mismo punto para la foto.'::text),
(310163,34463,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mémo : les 300 personnes ... montrer le même endroit pour la photo.'::text,'devraient'::text,'devraient'::text,'devraient'::text,'Mémo : les 300 personnes devraient montrer le même endroit pour la photo.'::text),
(310166,34463,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Not: 300 kişinin hepsi fotoğraf için aynı noktayı ...'::text,'göstermeli'::text,'göstermeli'::text,'göstermeli'::text,'Not: 300 kişinin hepsi fotoğraf için aynı noktayı göstermeli.'::text),
(310167,34463,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Feljegyzés: mind a 300 embernek ugyanarra a pontra ... mutatnia a fotóhoz.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Feljegyzés: mind a 300 embernek ugyanarra a pontra kellene mutatnia a fotóhoz.'::text),
(320151,35573,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! Diese winzige Straße ... hundert Touristen drauf!'::text,'hat'::text,'haben'::text,'hat'::text,'Albtraum! Diese winzige Straße hat hundert Touristen drauf!'::text),
(320155,35573,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! Ця крихітна вулиця ... на собі сотню туристів!'::text,'має'::text,'мати'::text,'має'::text,'Жах! Ця крихітна вулиця має на собі сотню туристів!'::text),
(320154,35573,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! ¡Esta calle diminuta ... cien turistas!'::text,'tiene'::text,'tienen'::text,'tiene'::text,'¡Pesadilla! ¡Esta calle diminuta tiene cien turistas!'::text),
(320153,35573,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! Cette toute petite rue ... cent touristes !'::text,'a'::text,'ont'::text,'a'::text,'Cauchemar ! Cette toute petite rue a cent touristes !'::text),
(320156,35573,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! Bu minicik sokağın üstünde yüz turist ...!'::text,'var'::text,'var'::text,'var'::text,'Kâbus! Bu minicik sokağın üstünde yüz turist var!'::text),
(320157,35573,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! Ennek az apró utcának száz turistája ...!'::text,'van'::text,'van'::text,'van'::text,'Rémálom! Ennek az apró utcának száz turistája van!'::text),
(320160,35574,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Stadtführerin kennt ... in dieser alten Stadt.'::text,'100 Straßen'::text,'100 Straße'::text,'100 Straßen'::text,'Die Stadtführerin kennt 100 Straßen in dieser alten Stadt.'::text),
(320164,35574,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гід знає ... в цьому старому місті.'::text,'100 вулиць'::text,'100 вулицю'::text,'100 вулиць'::text,'Гід знає 100 вулиць в цьому старому місті.'::text),
(320163,35574,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La guía conoce ... de este pueblo antiguo.'::text,'100 calles'::text,'100 calle'::text,'100 calles'::text,'La guía conoce 100 calles de este pueblo antiguo.'::text),
(320162,35574,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La guide connaît ... dans cette vieille ville.'::text,'100 rues'::text,'100 rue'::text,'100 rues'::text,'La guide connaît 100 rues dans cette vieille ville.'::text),
(320165,35574,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rehber bu eski kasabada ... biliyor.'::text,'100 sokak'::text,'100 sokak'::text,'100 sokak'::text,'Rehber bu eski kasabada 100 sokak biliyor.'::text),
(320166,35574,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az idegenvezető ... ismer ebben a régi városban.'::text,'100 utcát'::text,'100 utcát'::text,'100 utcát'::text,'Az idegenvezető 100 utcát ismer ebben a régi városban.'::text),
(320169,35575,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Führerin geht eine enge Straße hinauf. ... Straße ist sehr alt.'::text,'Die'::text,'Eine'::text,'Eine'::text,'Die Führerin geht eine enge Straße hinauf. Die Straße ist sehr alt.'::text),
(320173,35575,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гід іде вгору вузькою вулицею. ... Вулиця дуже стара.'::text,''::text,NULL::text,NULL::text,'Гід іде вгору вузькою вулицею. Вулиця дуже стара.'::text),
(320172,35575,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La guía sube por una calle estrecha. ... calle es muy antigua.'::text,'La'::text,'Una'::text,'Una'::text,'La guía sube por una calle estrecha. La calle es muy antigua.'::text),
