(320174,35575,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rehber dar bir sokaktan yukarı çıkıyor. ... Sokak çok eski.'::text,''::text,'Bir'::text,'Bir'::text,'Rehber dar bir sokaktan yukarı çıkıyor. Sokak çok eski.'::text),
(320175,35575,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az idegenvezető felmegy egy szűk utcán. ... utca nagyon régi.'::text,'Az'::text,'Egy'::text,'Egy'::text,'Az idegenvezető felmegy egy szűk utcán. Az utca nagyon régi.'::text),
(320178,35576,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Führerin zeigt die Straße hinauf: ... Häuser dort sind sehr alt.'::text,'jene'::text,'diese'::text,'dieses'::text,'Die Führerin zeigt die Straße hinauf: jene Häuser dort sind sehr alt.'::text),
(320182,35576,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гід показує вгору вулицею: ... будинки там дуже старі.'::text,'ті'::text,'ці'::text,'цей'::text,'Гід показує вгору вулицею: ті будинки там дуже старі.'::text),
(320181,35576,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La guía señala calle arriba: ... casas de allí son muy antiguas.'::text,'esas'::text,'estas'::text,'esta'::text,'La guía señala calle arriba: esas casas de allí son muy antiguas.'::text),
(320180,35576,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La guide montre le haut de la rue : ... maisons là-bas sont très anciennes.'::text,'ces'::text,'ces'::text,'cette'::text,'La guide montre le haut de la rue : ces maisons là-bas sont très anciennes.'::text),
(320183,35576,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rehber sokağın yukarısını gösteriyor: oradaki ... evler çok eski.'::text,'şu'::text,'bu'::text,'bu'::text,'Rehber sokağın yukarısını gösteriyor: oradaki şu evler çok eski.'::text),
(320184,35576,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az idegenvezető felmutat az utcán: ... a házak ott nagyon régiek.'::text,'azok'::text,'ezek'::text,'ez'::text,'Az idegenvezető felmutat az utcán: azok a házak ott nagyon régiek.'::text),
(320196,35578,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Straßentour beginnt ... zehn, weil zehn die Startzeit ist.'::text,'um'::text,'am'::text,'im'::text,'Die Straßentour beginnt um zehn, weil zehn die Startzeit ist.'::text),
(320200,35578,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Екскурсія вулицями починається ... десятій, бо десята — час початку.'::text,'о'::text,'на'::text,'у'::text,'Екскурсія вулицями починається о десятій, бо десята — час початку.'::text),
(320199,35578,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El recorrido por las calles empieza ... las diez porque las diez es la hora de inicio.'::text,'a'::text,'sobre'::text,'en'::text,'El recorrido por las calles empieza a las diez porque las diez es la hora de inicio.'::text),
(320198,35578,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La visite des rues commence ... dix heures parce que dix heures, c''est l''heure du début.'::text,'à'::text,'sur'::text,'dans'::text,'La visite des rues commence à dix heures parce que dix heures, c''est l''heure du début.'::text),
