(320205,35579,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! ... Touristen auf einer winzigen Straße!'::text,'Fünfzig'::text,'Fünfzigste'::text,'Fünfziger'::text,'Katastrophe! Fünfzig Touristen auf einer winzigen Straße!'::text),
