(315948,35106,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In seinen Badeshorts ... er sehr schnell rutschen.'::text,'kann'::text,'ist'::text,'kann'::text,'In seinen Badeshorts kann er sehr schnell rutschen.'::text),
(315952,35106,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У своїх плавальних шортах він ... ковзати дуже швидко.'::text,'може'::text,'є'::text,'може'::text,'У своїх плавальних шортах він може ковзати дуже швидко.'::text),
(315951,35106,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Con sus pantalones cortos de baño, ... deslizarse muy rápido.'::text,'puede'::text,'está'::text,'puede'::text,'Con sus pantalones cortos de baño, puede deslizarse muy rápido.'::text),
(315950,35106,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dans son short de bain, il ... glisser très vite.'::text,'peut'::text,'est'::text,'peut'::text,'Dans son short de bain, il peut glisser très vite.'::text),
(315953,35106,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mayo şortuyla çok hızlı ...'::text,'kayabilir'::text,NULL::text,'kayabilir'::text,'Mayo şortuyla çok hızlı kayabilir.'::text),
(315954,35106,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fürdő-rövidnadrágjában nagyon gyorsan ... csúszni.'::text,'tud'::text,'van'::text,'tud'::text,'A fürdő-rövidnadrágjában nagyon gyorsan tud csúszni.'::text),
(315957,35107,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, er muss ... Shorts für diese Rutsche einpacken.'::text,'3 Paar'::text,'3 Paar'::text,'3 Paar'::text,'Digga, er muss 3 Paar Shorts für diese Rutsche einpacken.'::text),
(315961,35107,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, він мусить узяти ... шортів для цієї гірки.'::text,'3 пари'::text,'3 пару'::text,'3 пари'::text,'Бро, він мусить узяти 3 пари шортів для цієї гірки.'::text),
(315960,35107,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, tiene que llevarse ... de pantalones cortos para este tobogán.'::text,'3 pares'::text,'3 par'::text,'3 pares'::text,'Tío, tiene que llevarse 3 pares de pantalones cortos para este tobogán.'::text),
(315959,35107,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, il doit emporter ... de short pour ce toboggan.'::text,'3 paires'::text,'3 paire'::text,'3 paires'::text,'Frérot, il doit emporter 3 paires de short pour ce toboggan.'::text),
(315962,35107,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu kaydırak için ... şort alması lazım.'::text,'3 çift'::text,'3 çift'::text,'3 çift'::text,'Kanka, bu kaydırak için 3 çift şort alması lazım.'::text),
(315963,35107,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... rövidnadrágot kell bepakolnia ehhez a csúszdához.'::text,'3 pár'::text,'3 pár'::text,'3 pár'::text,'Tesó, 3 pár rövidnadrágot kell bepakolnia ehhez a csúszdához.'::text),
(315966,35108,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, die Shorts sind schon ... krasse Wahl.'::text,'eine'::text,'eine'::text,'die'::text,'Digga, die Shorts sind schon eine krasse Wahl.'::text),
(315970,35108,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ці шорти — ... ну прям крутий вибір.'::text,''::text,NULL::text,NULL::text,'Бро, ці шорти — ну прям крутий вибір.'::text),
(315969,35108,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, esos pantalones cortos son ... elección bastante top.'::text,'una'::text,'una'::text,'la'::text,'Tío, esos pantalones cortos son una elección bastante top.'::text),
(315968,35108,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, ce short, c''est plutôt ... super choix.'::text,'un'::text,'un'::text,'le'::text,'Frérot, ce short, c''est plutôt un super choix.'::text),
(315971,35108,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o şort resmen ... harika seçim.'::text,'bir'::text,'bir'::text,NULL::text,'Kanka, o şort resmen bir harika seçim.'::text),
(315972,35108,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ez a rövidnadrág elég ... király választás.'::text,'egy'::text,'egy'::text,'a'::text,'Tesó, ez a rövidnadrág elég egy király választás.'::text),
(315975,35109,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Fahrer schaut runter auf ... nassen Shorts an seinen eigenen Beinen.'::text,'diese'::text,'diese'::text,'jene'::text,'Der Fahrer schaut runter auf diese nassen Shorts an seinen eigenen Beinen.'::text),
(315979,35109,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хлопець дивиться вниз на ... мокрі шорти на своїх ногах.'::text,'ці'::text,'ці'::text,'ті'::text,'Хлопець дивиться вниз на ці мокрі шорти на своїх ногах.'::text),
(315978,35109,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El chico mira hacia abajo a ... pantalones cortos mojados en sus propias piernas.'::text,'estos'::text,'este'::text,'ese'::text,'El chico mira hacia abajo a estos pantalones cortos mojados en sus propias piernas.'::text),
(315977,35109,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gars baisse les yeux sur ... short mouillé sur ses propres jambes.'::text,'ce'::text,'ce'::text,'ce'::text,'Le gars baisse les yeux sur ce short mouillé sur ses propres jambes.'::text),
(315980,35109,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kayan çocuk kendi bacaklarındaki ... ıslak şorta bakıyor.'::text,'bu'::text,'bu'::text,'şu'::text,'Kayan çocuk kendi bacaklarındaki bu ıslak şorta bakıyor.'::text),
(315981,35109,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A csúszó lenéz ... a vizes rövidnadrágra a saját lábán.'::text,'erre'::text,'erre'::text,'arra'::text,'A csúszó lenéz erre a vizes rövidnadrágra a saját lábán.'::text),
(315984,35110,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Junge rutscht in ... neuen Badeshorts runter.'::text,'seinen'::text,'ihren'::text,'seinen'::text,'Der Junge rutscht in seinen neuen Badeshorts runter.'::text),
(315988,35110,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хлопець з''їжджає в ... нових плавальних шортах.'::text,'своїх'::text,'своїх'::text,'своїх'::text,'Хлопець з''їжджає в своїх нових плавальних шортах.'::text),
(315987,35110,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El chico se tira con ... nuevos pantalones cortos de baño.'::text,'sus'::text,'sus'::text,'sus'::text,'El chico se tira con sus nuevos pantalones cortos de baño.'::text),
(315986,35110,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le garçon descend dans ... nouveau short de bain.'::text,'son'::text,'son'::text,'son'::text,'Le garçon descend dans son nouveau short de bain.'::text),
(315989,35110,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocuk ... yeni mayo şortuyla kayıyor.'::text,'onun'::text,'onun'::text,'onun'::text,'Çocuk onun yeni mayo şortuyla kayıyor.'::text),
(315990,35110,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiú az új ... csúszik le.'::text,'fürdő-rövidnadrágjában'::text,'fürdő-rövidnadrágjában'::text,'fürdő-rövidnadrágjában'::text,'A fiú az új fürdő-rövidnadrágjában csúszik le.'::text),
(315993,35111,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! So ... Wasser spritzt in seine Shorts!'::text,'viel'::text,'viele'::text,'irgendwelches'::text,'Katastrophe! So viel Wasser spritzt in seine Shorts!'::text),
(315997,35111,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Так ... води бризкає йому в шорти!'::text,'багато'::text,'багато'::text,'будь-якої'::text,'Катастрофа! Так багато води бризкає йому в шорти!'::text),
(315996,35111,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Catástrofe! ¡Le salpica ... agua dentro de los pantalones cortos!'::text,'muchísima'::text,'muchísimos'::text,'cualquier'::text,'¡Catástrofe! ¡Le salpica muchísima agua dentro de los pantalones cortos!'::text),
(315995,35111,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! ... eau gicle dans son short !'::text,'Tellement d'''::text,'Tellement d'''::text,'N''importe quelle'::text,'Catastrophe ! Tellement d'' eau gicle dans son short !'::text),
(315998,35111,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Şortunun içine o kadar ... su fışkırıyor!'::text,'çok'::text,'çok'::text,'herhangi bir'::text,'Felaket! Şortunun içine o kadar çok su fışkırıyor!'::text),
(315999,35111,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! Olyan ... víz spriccel fel a rövidnadrágjába!'::text,'sok'::text,'sok'::text,'bármilyen'::text,'Katasztrófa! Olyan sok víz spriccel fel a rövidnadrágjába!'::text),
(319584,35510,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Keiner bewegt sich! Der ganze Saal ... völlig reglos!'::text,'ist'::text,'sind'::text,'bin'::text,'Keiner bewegt sich! Der ganze Saal ist völlig reglos!'::text),
(319588,35510,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніхто не рухається! Уся зала ... абсолютно нерухома!'::text,'є'::text,'є'::text,'є'::text,'Ніхто не рухається! Уся зала є абсолютно нерухома!'::text),
(319587,35510,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Nadie se mueve! ¡Toda la sala ... completamente inmóvil!'::text,'está'::text,'están'::text,'estoy'::text,'¡Nadie se mueve! ¡Toda la sala está completamente inmóvil!'::text),
(319586,35510,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Personne ne bouge ! Toute la salle ... complètement immobile !'::text,'est'::text,'sont'::text,'suis'::text,'Personne ne bouge ! Toute la salle est complètement immobile !'::text),
(319589,35510,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kimse kıpırdamıyor! Bütün salon tamamen hareketsiz ...!'::text,''::text,NULL::text,NULL::text,'Kimse kıpırdamıyor! Bütün salon tamamen hareketsiz!'::text),
(319590,35510,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Senki sem mozdul! Az egész terem ... teljesen mozdulatlan!'::text,''::text,NULL::text,'vagyok'::text,'Senki sem mozdul! Az egész terem teljesen mozdulatlan!'::text),
(319602,35512,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Junge ... lange reglos auf der Linie.'::text,'stand'::text,'steht'::text,'stehen'::text,'Der Junge stand lange reglos auf der Linie.'::text),
(319606,35512,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хлопець довго ... нерухомо на лінії.'::text,'стояв'::text,'стоїть'::text,'стояти'::text,'Хлопець довго стояв нерухомо на лінії.'::text),
(319605,35512,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El chico ... quieto en la línea durante mucho tiempo.'::text,'se quedó'::text,'se queda'::text,'quedarse'::text,'El chico se quedó quieto en la línea durante mucho tiempo.'::text),
(319604,35512,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le garçon ... immobile sur la ligne pendant longtemps.'::text,'est resté'::text,'reste'::text,'rester'::text,'Le garçon est resté immobile sur la ligne pendant longtemps.'::text),
(319607,35512,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocuk uzun süre çizginin üstünde kıpırdamadan ...'::text,'durdu'::text,'durur'::text,'durmak'::text,'Çocuk uzun süre çizginin üstünde kıpırdamadan durdu.'::text),
(319608,35512,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiú sokáig mozdulatlanul ... a vonalon.'::text,'állt'::text,'áll'::text,'állni'::text,'A fiú sokáig mozdulatlanul állt a vonalon.'::text),
(319611,35513,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Junge rennt sonst in der Halle, aber gestern ... er still.'::text,'stand'::text,'steht'::text,NULL::text,'Der Junge rennt sonst in der Halle, aber gestern stand er still.'::text),
(319615,35513,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хлопець зазвичай бігає в залі, але вчора ... нерухомо.'::text,'стояв'::text,'стоїть'::text,NULL::text,'Хлопець зазвичай бігає в залі, але вчора стояв нерухомо.'::text),
(319614,35513,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El chico normalmente corre en el pabellón, pero ayer ... quieto.'::text,'se quedó'::text,'se queda'::text,NULL::text,'El chico normalmente corre en el pabellón, pero ayer se quedó quieto.'::text),
(319613,35513,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude le garçon court dans la salle, mais hier il ... immobile.'::text,'est resté'::text,'reste'::text,NULL::text,'D''habitude le garçon court dans la salle, mais hier il est resté immobile.'::text),
(319616,35513,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocuk genelde salonda koşar ama dün kıpırdamadan ...'::text,'durdu'::text,'durur'::text,NULL::text,'Çocuk genelde salonda koşar ama dün kıpırdamadan durdu.'::text),
(319617,35513,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiú általában fut a teremben, de tegnap mozdulatlanul ...'::text,'állt'::text,'áll'::text,NULL::text,'A fiú általában fut a teremben, de tegnap mozdulatlanul állt.'::text),
(319620,35514,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Statusbericht: 200 Schüler ... gerade reglos in der Halle.'::text,'stehen'::text,'stehen'::text,'stehen'::text,'Statusbericht: 200 Schüler stehen gerade reglos in der Halle.'::text),
(319624,35514,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Звіт про стан: 200 учнів саме зараз ... нерухомо в залі.'::text,'стоять'::text,'стоять'::text,'стоять'::text,'Звіт про стан: 200 учнів саме зараз стоять нерухомо в залі.'::text),
(319623,35514,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Informe de situación: 200 estudiantes ... quietos en el pabellón ahora mismo.'::text,'están de pie'::text,'están de pie'::text,'están de pie'::text,'Informe de situación: 200 estudiantes están de pie quietos en el pabellón ahora mismo.'::text),
(319622,35514,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rapport d''état : 200 élèves ... immobiles dans la salle en ce moment.'::text,'sont debout'::text,'sont debout'::text,'sont debout'::text,'Rapport d''état : 200 élèves sont debout immobiles dans la salle en ce moment.'::text),
(319625,35514,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Durum raporu: 200 öğrenci şu an salonda kıpırdamadan ...'::text,'duruyor'::text,'durur'::text,'duruyor'::text,'Durum raporu: 200 öğrenci şu an salonda kıpırdamadan duruyor.'::text),
(319626,35514,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Állapotjelentés: 200 diák ... most épp mozdulatlanul a teremben.'::text,'áll'::text,'áll'::text,'áll'::text,'Állapotjelentés: 200 diák áll most épp mozdulatlanul a teremben.'::text),
(319629,35515,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sonst rennen sie, aber jetzt ... sie still, weil sie sich nicht bewegen.'::text,'stehen'::text,'stehen'::text,NULL::text,'Sonst rennen sie, aber jetzt stehen sie still, weil sie sich nicht bewegen.'::text),
(319633,35515,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай вони бігають, але зараз ... нерухомо, бо не рухаються.'::text,'стоять'::text,'стоять'::text,NULL::text,'Зазвичай вони бігають, але зараз стоять нерухомо, бо не рухаються.'::text),
(319632,35515,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente corren, pero ahora ... quietos porque no se mueven.'::text,'están de pie'::text,'están de pie'::text,NULL::text,'Normalmente corren, pero ahora están de pie quietos porque no se mueven.'::text),
(319631,35515,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude ils courent, mais maintenant ils ... immobiles parce qu''ils ne bougent pas.'::text,'sont debout'::text,'sont debout'::text,NULL::text,'D''habitude ils courent, mais maintenant ils sont debout immobiles parce qu''ils ne bougent pas.'::text),
(319634,35515,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde koşarlar ama şimdi kıpırdamadan ... çünkü hareket etmiyorlar.'::text,'duruyorlar'::text,'dururlar'::text,NULL::text,'Genelde koşarlar ama şimdi kıpırdamadan duruyorlar çünkü hareket etmiyorlar.'::text),
(319635,35515,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában futnak, de most mozdulatlanul ..., mert nem mozognak.'::text,'állnak'::text,'állnak'::text,NULL::text,'Általában futnak, de most mozdulatlanul állnak, mert nem mozognak.'::text),
(319647,35517,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Schreckliche Spannung! Der Junge steht völlig reglos und atmet ...!'::text,'leise'::text,'leise'::text,'Stille'::text,'Schreckliche Spannung! Der Junge steht völlig reglos und atmet leise!'::text),
(319651,35517,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жахлива напруга! Хлопець стоїть зовсім нерухомо й дихає ...!'::text,'тихо'::text,'тихий'::text,'тиша'::text,'Жахлива напруга! Хлопець стоїть зовсім нерухомо й дихає тихо!'::text),
(319650,35517,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Tensión terrible! ¡El chico está completamente quieto y respira ...!'::text,'silenciosamente'::text,'silencioso'::text,'silencio'::text,'¡Tensión terrible! ¡El chico está completamente quieto y respira silenciosamente!'::text),
(319649,35517,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tension terrible ! Le garçon reste complètement immobile et respire ... !'::text,'silencieusement'::text,'silencieux'::text,'silence'::text,'Tension terrible ! Le garçon reste complètement immobile et respire silencieusement !'::text),
(319652,35517,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Korkunç bir gerilim! Çocuk tamamen hareketsiz duruyor ve ... nefes alıyor!'::text,'sessizce'::text,'sessiz'::text,'sessizlik'::text,'Korkunç bir gerilim! Çocuk tamamen hareketsiz duruyor ve sessizce nefes alıyor!'::text),
(319653,35517,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Borzasztó feszültség! A fiú teljesen mozdulatlanul áll, és ... lélegzik!'::text,'csendesen'::text,'csendes'::text,'csendesség'::text,'Borzasztó feszültség! A fiú teljesen mozdulatlanul áll, és csendesen lélegzik!'::text),
(307407,34157,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zwei riesige Reihen ... auf gegenüberliegenden Seiten, und niemand geht rüber!'::text,'sind'::text,'ist'::text,'bin'::text,'Zwei riesige Reihen sind auf gegenüberliegenden Seiten, und niemand geht rüber!'::text),
(307411,34157,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дві величезні шеренги ... на протилежних боках, і ніхто не переходить!'::text,'є'::text,'є'::text,'є'::text,'Дві величезні шеренги є на протилежних боках, і ніхто не переходить!'::text),
(307410,34157,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Dos filas enormes ... en lados opuestos y nadie cruza!'::text,'están'::text,'está'::text,'estoy'::text,'¡Dos filas enormes están en lados opuestos y nadie cruza!'::text),
(307409,34157,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deux immenses rangées ... sur des côtés opposés, et personne ne traverse !'::text,'sont'::text,'est'::text,'suis'::text,'Deux immenses rangées sont sur des côtés opposés, et personne ne traverse !'::text),
(307412,34157,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki devasa sıra karşı taraflarda ... ve kimse karşıya geçmiyor!'::text,''::text,NULL::text,NULL::text,'İki devasa sıra karşı taraflarda ve kimse karşıya geçmiyor!'::text),
(307413,34157,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Két hatalmas sor ... egymással szemben, és senki sem megy át!'::text,'van'::text,'van'::text,'vagyok'::text,'Két hatalmas sor van egymással szemben, és senki sem megy át!'::text),
(307416,34158,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sonst laufen die Leute über Plätze, aber heute ... sie auf gegenüberliegenden Seiten.'::text,'stehen'::text,'stehen'::text,NULL::text,'Sonst laufen die Leute über Plätze, aber heute stehen sie auf gegenüberliegenden Seiten.'::text),
(307420,34158,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай люди переходять площі, але сьогодні вони ... на протилежних боках.'::text,'стоять'::text,'стоять'::text,NULL::text,'Зазвичай люди переходять площі, але сьогодні вони стоять на протилежних боках.'::text),
(307419,34158,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente las personas cruzan las plazas, pero hoy ... en lados opuestos.'::text,'están de pie'::text,'están de pie'::text,NULL::text,'Normalmente las personas cruzan las plazas, pero hoy están de pie en lados opuestos.'::text),
(307418,34158,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude les gens traversent les places, mais aujourd''hui ils ... sur des côtés opposés.'::text,'sont debout'::text,'sont debout'::text,NULL::text,'D''habitude les gens traversent les places, mais aujourd''hui ils sont debout sur des côtés opposés.'::text),
(307421,34158,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İnsanlar genelde meydanlardan geçer ama bugün karşı taraflarda ...'::text,'duruyorlar'::text,'dururlar'::text,NULL::text,'İnsanlar genelde meydanlardan geçer ama bugün karşı taraflarda duruyorlar.'::text),
(307422,34158,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az emberek általában átsétálnak a tereken, de ma egymással szemben ...'::text,'állnak'::text,'állnak'::text,NULL::text,'Az emberek általában átsétálnak a tereken, de ma egymással szemben állnak.'::text),
(307425,34159,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die zwei gegenüberliegenden Reihen ... den ganzen Abend getrennt bleiben.'::text,'werden'::text,'sind'::text,NULL::text,'Die zwei gegenüberliegenden Reihen werden den ganzen Abend getrennt bleiben.'::text),
(307429,34159,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дві протилежні шеренги ... стояти окремо весь вечір.'::text,'будуть'::text,'є'::text,NULL::text,'Дві протилежні шеренги будуть стояти окремо весь вечір.'::text),
(307428,34159,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las dos filas opuestas ... separadas toda la tarde.'::text,'seguirán'::text,'están'::text,NULL::text,'Las dos filas opuestas seguirán separadas toda la tarde.'::text),
(307427,34159,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les deux rangées opposées ... séparées toute la soirée.'::text,'resteront'::text,'sont'::text,NULL::text,'Les deux rangées opposées resteront séparées toute la soirée.'::text),
(307430,34159,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Karşılıklı iki sıra bütün akşam ayrı ...'::text,'kalacak'::text,NULL::text,NULL::text,'Karşılıklı iki sıra bütün akşam ayrı kalacak.'::text),
(307431,34159,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A két szemközti sor egész este külön ... maradni.'::text,'fognak'::text,'vannak'::text,NULL::text,'A két szemközti sor egész este külön fognak maradni.'::text),
(307434,34160,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ganz klar ein freundlicher Plan: Die gegenüberliegenden Reihen ... die ganze Nacht getrennt bleiben.'::text,'werden'::text,'wird'::text,'werden'::text,'Ganz klar ein freundlicher Plan: Die gegenüberliegenden Reihen werden die ganze Nacht getrennt bleiben.'::text),
(307438,34160,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Явно дружній план: протилежні шеренги ... залишатися окремо всю ніч.'::text,'збираються'::text,'збирається'::text,'збираються'::text,'Явно дружній план: протилежні шеренги збираються залишатися окремо всю ніч.'::text),
(307437,34160,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un plan muy amistoso, claro: las filas opuestas ... quedarse separadas toda la noche.'::text,'van a'::text,'va a'::text,'van a'::text,'Un plan muy amistoso, claro: las filas opuestas van a quedarse separadas toda la noche.'::text),
(307436,34160,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un plan clairement amical : les rangées opposées ... rester séparées toute la nuit.'::text,'vont'::text,'va'::text,'vont'::text,'Un plan clairement amical : les rangées opposées vont rester séparées toute la nuit.'::text),
(307439,34160,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki dostça bir plan: karşılıklı sıralar bütün gece ayrı ...'::text,'kalacaklar'::text,'kalacak'::text,'kalacaklar'::text,'Belli ki dostça bir plan: karşılıklı sıralar bütün gece ayrı kalacaklar.'::text),
(307440,34160,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván baráti terv: a szemközti sorok egész éjjel külön ... maradni.'::text,'fognak'::text,'fog'::text,'fognak'::text,'Nyilván baráti terv: a szemközti sorok egész éjjel külön fognak maradni.'::text),
(307443,34161,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, die Reihen da gegenüber ... aufeinander losrennen, echt jetzt.'::text,'werden'::text,'werden'::text,NULL::text,'Yo, die Reihen da gegenüber werden aufeinander losrennen, echt jetzt.'::text),
(307447,34161,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, ті протилежні шеренги ... одна на одну, без брехні.'::text,'збираються кинутися'::text,'кинуться'::text,NULL::text,'Йо, ті протилежні шеренги збираються кинутися одна на одну, без брехні.'::text),
(307446,34161,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, esas filas opuestas ... lanzarse una contra otra, sin mentir.'::text,'van a'::text,NULL::text,NULL::text,'Tío, esas filas opuestas van a lanzarse una contra otra, sin mentir.'::text),
(307445,34161,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, ces rangées d''en face ... foncer l''une sur l''autre, sans mentir.'::text,'vont'::text,NULL::text,NULL::text,'Wesh, ces rangées d''en face vont foncer l''une sur l''autre, sans mentir.'::text),
(307448,34161,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, şu karşılıklı sıralar birbirine doğru ..., yemin ederim.'::text,'koşacak'::text,'koşacak'::text,NULL::text,'Kanka, şu karşılıklı sıralar birbirine doğru koşacak, yemin ederim.'::text),
(307449,34161,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, azok a szemközti sorok egymásnak ... rontani, komolyan.'::text,'fognak'::text,'fognak'::text,NULL::text,'Tesó, azok a szemközti sorok egymásnak fognak rontani, komolyan.'::text),
(307452,34162,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich, diese Seite ist viel ... als die gegenüber, Digga.'::text,'lauter'::text,'lauter'::text,'am lautesten'::text,'Ehrlich, diese Seite ist viel lauter als die gegenüber, Digga.'::text),
(307456,34162,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чесно, ця сторона набагато ... за протилежну, бро.'::text,'гучніша'::text,'більш гучна'::text,'найгучніша'::text,'Чесно, ця сторона набагато гучніша за протилежну, бро.'::text),
(307455,34162,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, este lado es mucho ... que el de enfrente, tío.'::text,'más ruidoso'::text,'más ruidoso'::text,'el más ruidoso'::text,'No te voy a mentir, este lado es mucho más ruidoso que el de enfrente, tío.'::text),
(307454,34162,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sans mentir, ce côté est carrément ... que le côté d''en face, frérot.'::text,'plus bruyant'::text,'plus bruyant'::text,'le plus bruyant'::text,'Sans mentir, ce côté est carrément plus bruyant que le côté d''en face, frérot.'::text),
(307457,34162,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, bu taraf karşı taraftan çok ..., kanka.'::text,'daha gürültülü'::text,'daha gürültülü'::text,'en gürültülü'::text,'Yalan yok, bu taraf karşı taraftan çok daha gürültülü, kanka.'::text),
(307458,34162,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem kamu, ez az oldal sokkal ..., mint a szemközti, tesó.'::text,'hangosabb'::text,'hangosabb'::text,'leghangosabb'::text,'Nem kamu, ez az oldal sokkal hangosabb, mint a szemközti, tesó.'::text),
(307470,34164,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die zwei Reihen stehen sich genau gegenüber, also schauen sie sich ... an.'::text,'direkt'::text,'direkt'::text,'Direktheit'::text,'Die zwei Reihen stehen sich genau gegenüber, also schauen sie sich direkt an.'::text),
(307474,34164,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дві шеренги точно навпроти, тож вони стоять лицем одна до одної ...'::text,'прямо.'::text,'прямий.'::text,'прямота.'::text,'Дві шеренги точно навпроти, тож вони стоять лицем одна до одної прямо.'::text),
(307473,34164,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las dos filas están justo enfrente, así que se miran ...'::text,'directamente.'::text,'directo.'::text,'franqueza.'::text,'Las dos filas están justo enfrente, así que se miran directamente.'::text),
(307472,34164,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les deux rangées sont exactement opposées, donc elles se font face ...'::text,'directement.'::text,'direct.'::text,'franchise.'::text,'Les deux rangées sont exactement opposées, donc elles se font face directement.'::text),
(307475,34164,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İki sıra tam karşı karşıya, bu yüzden birbirlerine ... bakıyorlar.'::text,'doğrudan doğruya'::text,'doğrudan'::text,'doğrudanlık'::text,'İki sıra tam karşı karşıya, bu yüzden birbirlerine doğrudan doğruya bakıyorlar.'::text),
(307476,34164,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A két sor pontosan szemben áll, így egymással ... néznek szembe.'::text,'közvetlenül'::text,'közvetlen'::text,'közvetlenség'::text,'A két sor pontosan szemben áll, így egymással közvetlenül néznek szembe.'::text),
(315282,35032,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Zwölf Freunde rennen, und da sind ... Schatten auf den Steinen.'::text,'zwölf'::text,'zwölfte'::text,'Zwölfen'::text,'Zwölf Freunde rennen, und da sind zwölf Schatten auf den Steinen.'::text),
(315286,35032,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дванадцятеро друзів біжать, і на каменях ... тіней.'::text,'дванадцять'::text,'дванадцятий'::text,'дванадцятки'::text,'Дванадцятеро друзів біжать, і на каменях дванадцять тіней.'::text),
(315285,35032,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Doce amigos corren y hay ... sombras en las piedras.'::text,'doce'::text,'duodécimas'::text,'doce'::text,'Doce amigos corren y hay doce sombras en las piedras.'::text),
(315284,35032,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Douze amis courent, et il y a ... ombres sur les pierres.'::text,'douze'::text,'douzièmes'::text,'douze'::text,'Douze amis courent, et il y a douze ombres sur les pierres.'::text),
(315287,35032,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On iki arkadaş koşuyor ve taşların üstünde ... gölge var.'::text,'on iki'::text,'on ikinci'::text,'on ikiler'::text,'On iki arkadaş koşuyor ve taşların üstünde on iki gölge var.'::text),
(315288,35032,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tizenkét barát fut, és ... árnyék van a köveken.'::text,'tizenkét'::text,'tizenkettedik'::text,'tizenkettesek'::text,'Tizenkét barát fut, és tizenkét árnyék van a köveken.'::text),
(315300,35034,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, schau dir die tiefe Sonne an, ihre Schatten ... mega lang sein, Alter.'::text,'werden'::text,'werden'::text,'werden'::text,'Yo, schau dir die tiefe Sonne an, ihre Schatten werden mega lang sein, Alter.'::text),
(315304,35034,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, глянь на низьке сонце, їхні тіні ... супердовгими, чувак.'::text,'будуть'::text,'будуть'::text,'будуть'::text,'Йо, глянь на низьке сонце, їхні тіні будуть супердовгими, чувак.'::text),
(315303,35034,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, mira el sol tan bajo, sus sombras ... superlargas, tronco.'::text,'van a ser'::text,'serán'::text,'van a ser'::text,'Tío, mira el sol tan bajo, sus sombras van a ser superlargas, tronco.'::text),
(315302,35034,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, regarde le soleil bas, leurs ombres ... super longues, mec.'::text,'vont être'::text,'seront'::text,'vont être'::text,'Wesh, regarde le soleil bas, leurs ombres vont être super longues, mec.'::text),
(315305,35034,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, alçak güneşe bak, gölgeleri süper uzun ..., dostum.'::text,'olacak'::text,'olacak'::text,'olacak'::text,'Kanka, alçak güneşe bak, gölgeleri süper uzun olacak, dostum.'::text),
(315306,35034,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, nézd, milyen alacsonyan van a nap, az árnyékuk szuperhosszú ..., haver.'::text,'lesz'::text,'lesz'::text,'lesz'::text,'Tesó, nézd, milyen alacsonyan van a nap, az árnyékuk szuperhosszú lesz, haver.'::text),
(315309,35035,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Prognose: Die Sonne steht tief, also ... die Schatten um 50 Prozent wachsen.'::text,'werden'::text,'werden'::text,NULL::text,'Prognose: Die Sonne steht tief, also werden die Schatten um 50 Prozent wachsen.'::text),
(315313,35035,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Прогноз: сонце низько, тож тіні ... на 50 відсотків.'::text,'збираються вирости'::text,'виростуть'::text,NULL::text,'Прогноз: сонце низько, тож тіні збираються вирости на 50 відсотків.'::text),
(315312,35035,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Previsión: el sol está bajo, así que las sombras ... crecer un 50 por ciento.'::text,'van a'::text,NULL::text,NULL::text,'Previsión: el sol está bajo, así que las sombras van a crecer un 50 por ciento.'::text),
(315311,35035,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Prévision : le soleil est bas, donc les ombres ... grandir de 50 pour cent.'::text,'vont'::text,NULL::text,NULL::text,'Prévision : le soleil est bas, donc les ombres vont grandir de 50 pour cent.'::text),
(315314,35035,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tahmin: güneş alçakta, bu yüzden gölgeler yüzde 50 ...'::text,'uzayacak'::text,'uzayacak'::text,NULL::text,'Tahmin: güneş alçakta, bu yüzden gölgeler yüzde 50 uzayacak.'::text),
(315315,35035,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Előrejelzés: alacsonyan jár a nap, így az árnyékok 50 százalékkal ... nőni.'::text,'fognak'::text,'fognak'::text,NULL::text,'Előrejelzés: alacsonyan jár a nap, így az árnyékok 50 százalékkal fognak nőni.'::text),
(315318,35036,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein Schatten braucht ..., also rennen die Freunde in der Sonne.'::text,'Sonnenschein'::text,'Sonnenschein'::text,'einen Sonnenschein'::text,'Ein Schatten braucht Sonnenschein, also rennen die Freunde in der Sonne.'::text),
(315322,35036,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тіні потрібне ..., тож друзі бігають на сонці.'::text,'сонячне світло'::text,'сонячне світло'::text,'сонячне світло'::text,'Тіні потрібне сонячне світло, тож друзі бігають на сонці.'::text),
(315321,35036,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Una sombra necesita ..., así que los amigos corren al sol.'::text,'luz del sol'::text,'luz del sol'::text,'una luz del sol'::text,'Una sombra necesita luz del sol, así que los amigos corren al sol.'::text),
(315320,35036,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Une ombre a besoin de ..., alors les amis courent au soleil.'::text,'soleil'::text,'soleil'::text,'un soleil'::text,'Une ombre a besoin de soleil, alors les amis courent au soleil.'::text),
(315323,35036,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gölgenin ... ihtiyacı var, bu yüzden arkadaşlar güneşte koşuyor.'::text,'güneş ışığına'::text,'güneş ışıklarına'::text,'bir güneş ışığına'::text,'Gölgenin güneş ışığına ihtiyacı var, bu yüzden arkadaşlar güneşte koşuyor.'::text),
(315324,35036,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az árnyékhoz ... kell, ezért a barátok a napon futnak.'::text,'napfény'::text,'napfény'::text,'egy napfény'::text,'Az árnyékhoz napfény kell, ezért a barátok a napon futnak.'::text),
(315327,35037,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Albtraum! So ... Schatten jagen sie über den Platz!'::text,'viele'::text,'viel'::text,'irgendwelche'::text,'Albtraum! So viele Schatten jagen sie über den Platz!'::text),
(315331,35037,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жах! Так ... тіней женеться за ними площею!'::text,'багато'::text,'багато'::text,'будь-яких'::text,'Жах! Так багато тіней женеться за ними площею!'::text),
(315330,35037,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Pesadilla! ¡... sombras los persiguen por la plaza!'::text,'Muchísimas'::text,'Muchísima'::text,'Cualquier'::text,'¡Pesadilla! ¡Muchísimas sombras los persiguen por la plaza!'::text),
(315329,35037,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cauchemar ! ... ombres les poursuivent sur la place !'::text,'Tellement d'''::text,'Tellement d'''::text,'N''importe quelles'::text,'Cauchemar ! Tellement d'' ombres les poursuivent sur la place !'::text),
(315332,35037,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kâbus! O kadar ... gölge onları meydan boyunca kovalıyor!'::text,'çok'::text,'çok'::text,'herhangi bir'::text,'Kâbus! O kadar çok gölge onları meydan boyunca kovalıyor!'::text),
(315333,35037,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rémálom! Olyan ... árnyék kergeti őket a téren át!'::text,'sok'::text,'sok'::text,'bármilyen'::text,'Rémálom! Olyan sok árnyék kergeti őket a téren át!'::text),
(315336,35038,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Absolut gruselig! Da ... ein riesiger Schatten hinter jedem Läufer!'::text,'ist'::text,'sind'::text,'sein'::text,'Absolut gruselig! Da ist ein riesiger Schatten hinter jedem Läufer!'::text),
(315340,35038,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Просто жахливо! Позаду кожного бігуна ... гігантська тінь!'::text,'є'::text,'є'::text,'бути'::text,'Просто жахливо! Позаду кожного бігуна є гігантська тінь!'::text),
(315339,35038,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Absolutamente aterrador! ¡... una sombra gigante detrás de cada corredor!'::text,'Hay'::text,'Hay'::text,'Hay'::text,'¡Absolutamente aterrador! ¡Hay una sombra gigante detrás de cada corredor!'::text),
(315338,35038,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Absolument terrifiant ! ... une ombre géante derrière chaque coureur !'::text,'Il y a'::text,'Il y a'::text,'Il y a'::text,'Absolument terrifiant ! Il y a une ombre géante derrière chaque coureur !'::text),
(315341,35038,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tam bir dehşet! Her koşucunun arkasında dev bir gölge ...!'::text,'var'::text,'var'::text,'olmak'::text,'Tam bir dehşet! Her koşucunun arkasında dev bir gölge var!'::text),
(315342,35038,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Teljesen ijesztő! Minden futó mögött ... egy óriási árnyék!'::text,'van'::text,'vannak'::text,'lenni'::text,'Teljesen ijesztő! Minden futó mögött van egy óriási árnyék!'::text),
(301611,33513,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein Fremder ... bei der Gruppenumarmung auf dem Platz mit.'::text,'macht'::text,'machen'::text,'machend'::text,'Ein Fremder macht bei der Gruppenumarmung auf dem Platz mit.'::text),
(301615,33513,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Незнайомець ... до групових обіймів на площі.'::text,'приєднується'::text,'приєднуватися'::text,'приєднуючись'::text,'Незнайомець приєднується до групових обіймів на площі.'::text),
(301614,33513,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un desconocido ... al abrazo en grupo de la plaza.'::text,'se une'::text,'unirse'::text,'uniéndose'::text,'Un desconocido se une al abrazo en grupo de la plaza.'::text),
(301613,33513,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un inconnu ... le câlin collectif sur la place.'::text,'rejoint'::text,'rejoindre'::text,'rejoignant'::text,'Un inconnu rejoint le câlin collectif sur la place.'::text),
(301616,33513,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir yabancı meydandaki grup sarılmasına ...'::text,'katılır'::text,'katılmak'::text,'katılarak'::text,'Bir yabancı meydandaki grup sarılmasına katılır.'::text),
(301617,33513,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy idegen ... a csoportos öleléshez a téren.'::text,'csatlakozik'::text,'csatlakozni'::text,'csatlakozó'::text,'Egy idegen csatlakozik a csoportos öleléshez a téren.'::text),
(301629,33515,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... viele Leute machen bei der Umarmung mit? Etwa 200, ein neues Ziel.'::text,'Wie'::text,'Was'::text,'Wer'::text,'Wie viele Leute machen bei der Umarmung mit? Etwa 200, ein neues Ziel.'::text),
(301633,33515,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... людей приєднується до обіймів? Близько 200, нова ціль.'::text,'Скільки'::text,'Що'::text,'Хто'::text,'Скільки людей приєднується до обіймів? Близько 200, нова ціль.'::text),
(301632,33515,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... personas se unen al abrazo? Unas 200, un nuevo objetivo.'::text,'Cuántas'::text,'Qué'::text,'Quién'::text,'¿Cuántas personas se unen al abrazo? Unas 200, un nuevo objetivo.'::text),
(301631,33515,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... de personnes rejoignent le câlin ? Environ 200, un nouvel objectif.'::text,'Combien'::text,'Que'::text,'Qui'::text,'Combien de personnes rejoignent le câlin ? Environ 200, un nouvel objectif.'::text),
(301634,33515,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sarılmaya ... kişi katılıyor? Yaklaşık 200, yeni hedef.'::text,'kaç'::text,'ne'::text,'kim'::text,'Sarılmaya kaç kişi katılıyor? Yaklaşık 200, yeni hedef.'::text),
(301635,33515,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ember csatlakozik az öleléshez? Körülbelül 200, új cél.'::text,'Hány'::text,'Mi'::text,'Ki'::text,'Hány ember csatlakozik az öleléshez? Körülbelül 200, új cél.'::text),
(301638,33516,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ein Fremder ... bei der Umarmung mit, weil die Umarmung da war.'::text,'machte'::text,'macht'::text,'machte'::text,'Ein Fremder machte bei der Umarmung mit, weil die Umarmung da war.'::text),
(301642,33516,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Незнайомець ... до обіймів, бо обійми там були.'::text,'приєднався'::text,'приєднується'::text,'приєднався'::text,'Незнайомець приєднався до обіймів, бо обійми там були.'::text),
(301641,33516,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un desconocido ... al abrazo porque el abrazo estaba ahí.'::text,'se unió'::text,'se une'::text,'se unió'::text,'Un desconocido se unió al abrazo porque el abrazo estaba ahí.'::text),
(301640,33516,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Un inconnu ... le câlin parce que le câlin était là.'::text,'a rejoint'::text,'rejoint'::text,'a rejoint'::text,'Un inconnu a rejoint le câlin parce que le câlin était là.'::text),
(301643,33516,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir yabancı sarılmaya ... çünkü sarılma oradaydı.'::text,'katıldı'::text,'katılır'::text,'katıldı'::text,'Bir yabancı sarılmaya katıldı çünkü sarılma oradaydı.'::text),
(301644,33516,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy idegen ... az öleléshez, mert az ölelés ott volt.'::text,'csatlakozott'::text,'csatlakozik'::text,'csatlakozott'::text,'Egy idegen csatlakozott az öleléshez, mert az ölelés ott volt.'::text),
(301647,33517,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalerweise mache ich bei nichts mit, aber gestern ... ich bei einer Umarmung von Hunderten mit! Unglaublich!'::text,'machte'::text,'mache'::text,NULL::text,'Normalerweise mache ich bei nichts mit, aber gestern machte ich bei einer Umarmung von Hunderten mit! Unglaublich!'::text),
(301651,33517,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай я ні до чого не приєднуюся, але вчора я ... до обіймів сотень людей! Неймовірно!'::text,'приєднався'::text,'приєднуюся'::text,NULL::text,'Зазвичай я ні до чого не приєднуюся, але вчора я приєднався до обіймів сотень людей! Неймовірно!'::text),
(301650,33517,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Normalmente no me uno a nada, pero ayer ... a un abrazo de cientos de personas! ¡Increíble!'::text,'me uní'::text,'me uno'::text,NULL::text,'¡Normalmente no me uno a nada, pero ayer me uní a un abrazo de cientos de personas! ¡Increíble!'::text),
(301649,33517,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude je ne rejoins rien, mais hier ... un câlin de centaines de personnes ! Incroyable !'::text,'j''ai rejoint'::text,'je rejoins'::text,NULL::text,'D''habitude je ne rejoins rien, mais hier j''ai rejoint un câlin de centaines de personnes ! Incroyable !'::text),
(301652,33517,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalde hiçbir şeye katılmam ama dün yüzlerce kişilik bir sarılmaya ...! İnanılmaz!'::text,'katıldım'::text,'katılırım'::text,NULL::text,'Normalde hiçbir şeye katılmam ama dün yüzlerce kişilik bir sarılmaya katıldım! İnanılmaz!'::text),
(301653,33517,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában semmihez sem csatlakozom, de tegnap ... egy több száz fős öleléshez! Hihetetlen!'::text,'csatlakoztam'::text,'csatlakozom'::text,NULL::text,'Általában semmihez sem csatlakozom, de tegnap csatlakoztam egy több száz fős öleléshez! Hihetetlen!'::text),
(301656,33518,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nein! Gerade ... jeder bei der Umarmung mit! Keiner entkommt!'::text,'macht'::text,'macht'::text,'macht'::text,'Nein! Gerade macht jeder bei der Umarmung mit! Keiner entkommt!'::text),
(301660,33518,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ні! Саме зараз кожен ... до обіймів! Ніхто не втече!'::text,'приєднується'::text,'приєднується'::text,'приєднується'::text,'Ні! Саме зараз кожен приєднується до обіймів! Ніхто не втече!'::text),
(301659,33518,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡No! ¡Ahora mismo todo el mundo ... al abrazo! ¡Nadie se escapa!'::text,'se está uniendo'::text,'se une'::text,'se están uniendo'::text,'¡No! ¡Ahora mismo todo el mundo se está uniendo al abrazo! ¡Nadie se escapa!'::text),
(301658,33518,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Non ! En ce moment, tout le monde ... le câlin ! Personne n''y échappe !'::text,'est en train de rejoindre'::text,'rejoint'::text,'sont en train de rejoindre'::text,'Non ! En ce moment, tout le monde est en train de rejoindre le câlin ! Personne n''y échappe !'::text),
(301661,33518,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hayır! Şu an herkes sarılmaya ...! Kimse kaçamıyor!'::text,'katılıyor'::text,'katılır'::text,'katılıyorlar'::text,'Hayır! Şu an herkes sarılmaya katılıyor! Kimse kaçamıyor!'::text),
(301662,33518,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ne! Épp most mindenki ... az öleléshez! Senki sem menekül!'::text,'csatlakozik'::text,'csatlakozik'::text,'csatlakozik'::text,'Ne! Épp most mindenki csatlakozik az öleléshez! Senki sem menekül!'::text),
(301674,33520,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Umarmung ist schon riesig, ... noch mehr Leute machen mit.'::text,'aber'::text,'weil'::text,'also'::text,'Die Umarmung ist schon riesig, aber noch mehr Leute machen mit.'::text),
(301678,33520,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Обійми вже величезні, ... ще більше людей досі приєднуються.'::text,'але'::text,'бо'::text,'тому'::text,'Обійми вже величезні, але ще більше людей досі приєднуються.'::text),
(301677,33520,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El abrazo ya es enorme, ... aún se une más gente.'::text,'pero'::text,'porque'::text,'así que'::text,'El abrazo ya es enorme, pero aún se une más gente.'::text),
(301676,33520,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le câlin est déjà énorme, ... encore plus de gens le rejoignent.'::text,'mais'::text,'parce que'::text,'donc'::text,'Le câlin est déjà énorme, mais encore plus de gens le rejoignent.'::text),
(301679,33520,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sarılma zaten kocaman ... daha fazla insan hâlâ katılıyor.'::text,'ama'::text,'çünkü'::text,'bu yüzden'::text,'Sarılma zaten kocaman ama daha fazla insan hâlâ katılıyor.'::text),
(301680,33520,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ölelés már így is hatalmas, ... még mindig egyre többen csatlakoznak.'::text,'de'::text,'mert'::text,'ezért'::text,'Az ölelés már így is hatalmas, de még mindig egyre többen csatlakoznak.'::text),
(293502,32612,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ist berühmt, weil die Leute sie filmen, also ... sie jetzt auf eine Laterne.'::text,'klettert'::text,'klettert'::text,NULL::text,'Sie ist berühmt, weil die Leute sie filmen, also klettert sie jetzt auf eine Laterne.'::text),
(293506,32612,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона знаменита, бо люди її знімають, тож зараз вона ... на ліхтарний стовп.'::text,'лізе'::text,'лізе'::text,NULL::text,'Вона знаменита, бо люди її знімають, тож зараз вона лізе на ліхтарний стовп.'::text),
(293505,32612,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es famosa porque la gente la graba, así que ahora ... a una farola.'::text,'está trepando'::text,'trepa'::text,NULL::text,'Es famosa porque la gente la graba, así que ahora está trepando a una farola.'::text),
(293504,32612,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle est célèbre parce que les gens la filment, donc maintenant elle ... sur un lampadaire.'::text,'est en train de grimper'::text,'grimpe'::text,NULL::text,'Elle est célèbre parce que les gens la filment, donc maintenant elle est en train de grimper sur un lampadaire.'::text),
(293507,32612,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ünlü çünkü insanlar onu çekiyor, bu yüzden şimdi bir sokak lambasına ...'::text,'tırmanıyor'::text,'tırmanır'::text,NULL::text,'Ünlü çünkü insanlar onu çekiyor, bu yüzden şimdi bir sokak lambasına tırmanıyor.'::text),
(293508,32612,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Híres, mert az emberek filmezik, ezért most ... egy lámpaoszlopra.'::text,'mászik'::text,'mászik'::text,NULL::text,'Híres, mert az emberek filmezik, ezért most mászik egy lámpaoszlopra.'::text),
(293511,32613,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nach heute Nacht ... sie für immer berühmt sein!'::text,'wird'::text,'ist'::text,NULL::text,'Nach heute Nacht wird sie für immer berühmt sein!'::text),
(293515,32613,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Після цієї ночі вона ... знаменитою назавжди!'::text,'буде'::text,'є'::text,NULL::text,'Після цієї ночі вона буде знаменитою назавжди!'::text),
(293514,32613,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Después de esta noche ... famosa para siempre!'::text,'será'::text,'está'::text,NULL::text,'¡Después de esta noche será famosa para siempre!'::text),
(293513,32613,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Après ce soir, elle ... célèbre pour toujours !'::text,'sera'::text,'est'::text,NULL::text,'Après ce soir, elle sera célèbre pour toujours !'::text),
(293516,32613,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu geceden sonra sonsuza kadar ünlü ...!'::text,'olacak'::text,NULL::text,NULL::text,'Bu geceden sonra sonsuza kadar ünlü olacak!'::text),
(293517,32613,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma éjszaka után örökre híres ...!'::text,'lesz'::text,NULL::text,NULL::text,'Ma éjszaka után örökre híres lesz!'::text),
(293520,32614,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihr Plan ist einfach: Sie ... heute Abend berühmt sein.'::text,'wird'::text,'werden'::text,'wird'::text,'Ihr Plan ist einfach: Sie wird heute Abend berühmt sein.'::text),
(293524,32614,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її план простий: вона ... стати знаменитою сьогодні ввечері.'::text,'збирається'::text,'збираються'::text,'збирається'::text,'Її план простий: вона збирається стати знаменитою сьогодні ввечері.'::text),
(293523,32614,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su plan es sencillo: ... ser famosa esta noche.'::text,'va a'::text,'van a'::text,'va a'::text,'Su plan es sencillo: va a ser famosa esta noche.'::text),
(293522,32614,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Son plan est simple : elle ... être célèbre ce soir.'::text,'va'::text,'vont'::text,'va'::text,'Son plan est simple : elle va être célèbre ce soir.'::text),
(293525,32614,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Planı basit: bu akşam ünlü ...'::text,'olacak'::text,'olacaklar'::text,'olacak'::text,'Planı basit: bu akşam ünlü olacak.'::text),
(293526,32614,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egyszerű a terve: ma este híres ... lenni.'::text,'fog'::text,'fognak'::text,'fog'::text,'Egyszerű a terve: ma este híres fog lenni.'::text),
(293529,32615,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alle filmen sie. Sie ... bis morgen berühmt sein.'::text,'wird'::text,'wird'::text,NULL::text,'Alle filmen sie. Sie wird bis morgen berühmt sein.'::text),
(293533,32615,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Усі її знімають. Вона ... знаменитою до завтра.'::text,'буде'::text,'буде'::text,NULL::text,'Усі її знімають. Вона буде знаменитою до завтра.'::text),
(293532,32615,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Todo el mundo la está grabando. ... ser famosa para mañana.'::text,'Va a'::text,NULL::text,NULL::text,'Todo el mundo la está grabando. Va a ser famosa para mañana.'::text),
(293531,32615,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tout le monde la filme. Elle ... être célèbre d''ici demain.'::text,'va'::text,NULL::text,NULL::text,'Tout le monde la filme. Elle va être célèbre d''ici demain.'::text),
(293534,32615,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Herkes onu çekiyor. Yarına kadar ünlü ...'::text,'olacak'::text,'olacak'::text,NULL::text,'Herkes onu çekiyor. Yarına kadar ünlü olacak.'::text),
(293535,32615,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mindenki őt filmezi. Holnapra híres ...'::text,'lesz'::text,'lesz'::text,NULL::text,'Mindenki őt filmezi. Holnapra híres lesz.'::text),
(293538,32616,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Klar, nach einer Laterne ist sie ... als jeder Filmstar.'::text,'berühmter'::text,'berühmter'::text,'am berühmtesten'::text,'Klar, nach einer Laterne ist sie berühmter als jeder Filmstar.'::text),
(293542,32616,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Очевидно, після одного ліхтаря вона ... за будь-яку кінозірку.'::text,'більш знаменита'::text,'знаменитіша'::text,'найзнаменитіша'::text,'Очевидно, після одного ліхтаря вона більш знаменита за будь-яку кінозірку.'::text),
(293541,32616,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claro, después de una farola es ... que cualquier estrella de cine.'::text,'más famosa'::text,'más famosa'::text,'la más famosa'::text,'Claro, después de una farola es más famosa que cualquier estrella de cine.'::text),
(293540,32616,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Évidemment, elle est ... que n''importe quelle star de cinéma après un seul lampadaire.'::text,'plus célèbre'::text,'plus célèbre'::text,'la plus célèbre'::text,'Évidemment, elle est plus célèbre que n''importe quelle star de cinéma après un seul lampadaire.'::text),
(293543,32616,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki tek bir sokak lambasından sonra herhangi bir film yıldızından ...'::text,'daha ünlü'::text,'daha ünlü'::text,'en ünlü'::text,'Belli ki tek bir sokak lambasından sonra herhangi bir film yıldızından daha ünlü.'::text),
(293544,32616,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilvánvaló, hogy egyetlen lámpaoszlop után ..., mint bármelyik filmsztár.'::text,'híresebb'::text,'híresebb'::text,'leghíresebb'::text,'Nyilvánvaló, hogy egyetlen lámpaoszlop után híresebb, mint bármelyik filmsztár.'::text),
(293556,32618,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, sie ist so ... berühmt geworden, echt jetzt.'::text,'schnell'::text,'schneller'::text,'Schnelligkeit'::text,'Alter, sie ist so schnell berühmt geworden, echt jetzt.'::text),
(293560,32618,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чувак, вона так ... стала знаменитою, без брехні.'::text,'швидко'::text,'швидше'::text,'швидкість'::text,'Чувак, вона так швидко стала знаменитою, без брехні.'::text),
(293559,32618,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, se hizo famosa tan ..., en serio.'::text,'rápidamente'::text,'más rápido'::text,'rapidez'::text,'Tío, se hizo famosa tan rápidamente, en serio.'::text),
