(298059,33118,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su guitarra tiene seis ...'::text,'cuerdas.'::text,'cuerda.'::text,'cuerdas.'::text,'Su guitarra tiene seis cuerdas.'::text),
(298058,33118,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sa guitare a six ...'::text,'cordes.'::text,'corde.'::text,'cordes.'::text,'Sa guitare a six cordes.'::text),
