(298065,33119,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nee Digga, das ist keine Geige, das ist ... Gitarre.'::text,'eine'::text,'eine'::text,'die'::text,'Nee Digga, das ist keine Geige, das ist eine Gitarre.'::text),
