(298068,33119,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué va, tío, eso no es un violín, es ... guitarra.'::text,'una'::text,'una'::text,'la'::text,'Qué va, tío, eso no es un violín, es una guitarra.'::text),
(298067,33119,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mais non frérot, c''est pas un violon, c''est ... guitare.'::text,'une'::text,'une'::text,'la'::text,'Mais non frérot, c''est pas un violon, c''est une guitare.'::text),
(298070,33119,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yok kanka, o keman değil, o ... gitar.'::text,'bir'::text,'bir'::text,NULL::text,'Yok kanka, o keman değil, o bir gitar.'::text),
(298071,33119,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Á, tesó, az nem hegedű, az ... gitár.'::text,'egy'::text,'egy'::text,'a'::text,'Á, tesó, az nem hegedű, az egy gitár.'::text),
(298074,33120,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, ... Leute werden den ganzen Tag seine Gitarre filmen.'::text,'jene'::text,'jene'::text,'diese'::text,'Digga, jene Leute werden den ganzen Tag seine Gitarre filmen.'::text),
(298078,33120,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ... люди цілий день зніматимуть його гітару.'::text,'ті'::text,'той'::text,'цей'::text,'Бро, ті люди цілий день зніматимуть його гітару.'::text),
(298077,33120,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ... personas van a grabar su guitarra todo el día.'::text,'esas'::text,'esa'::text,'esta'::text,'Tío, esas personas van a grabar su guitarra todo el día.'::text),
(298076,33120,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, ... gens vont filmer sa guitare toute la journée.'::text,'ces'::text,'ce'::text,'ce'::text,'Frérot, ces gens vont filmer sa guitare toute la journée.'::text),
(298079,33120,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ... insanlar bütün gün onun gitarını çekecek.'::text,'şu'::text,'şu'::text,'bu'::text,'Kanka, şu insanlar bütün gün onun gitarını çekecek.'::text),
(298080,33120,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... az emberek egész nap az ő gitárját fogják filmezni.'::text,'azok'::text,'az'::text,'ez'::text,'Tesó, azok az emberek egész nap az ő gitárját fogják filmezni.'::text),
(298083,33121,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Budget: 0 Euro. Er spielt ... Gitarre gratis.'::text,'seine'::text,'ihre'::text,'seine'::text,'Budget: 0 Euro. Er spielt seine Gitarre gratis.'::text),
(298087,33121,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бюджет: 0 євро. Він грає на ... гітарі безкоштовно.'::text,'своїй'::text,'своїй'::text,'своїй'::text,'Бюджет: 0 євро. Він грає на своїй гітарі безкоштовно.'::text),
(298086,33121,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Presupuesto: 0 euros. Toca ... guitarra gratis.'::text,'su'::text,'su'::text,'su'::text,'Presupuesto: 0 euros. Toca su guitarra gratis.'::text),
(298085,33121,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Budget : 0 euro. Il joue de ... guitare gratuitement.'::text,'sa'::text,'sa'::text,'sa'::text,'Budget : 0 euro. Il joue de sa guitare gratuitement.'::text),
(298088,33121,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütçe: 0 euro. ... gitarını bedavaya çalıyor.'::text,'Onun'::text,'Onun'::text,'Onun'::text,'Bütçe: 0 euro. Onun gitarını bedavaya çalıyor.'::text),
(298089,33121,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Költségvetés: 0 euró. Ingyen játszik a ...'::text,'gitárján.'::text,'gitárján.'::text,'gitárján.'::text,'Költségvetés: 0 euró. Ingyen játszik a gitárján.'::text),
(298101,33123,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Büroangestellte bleiben stehen, um seiner Gitarre zuzuhören.'::text,'Viele'::text,'Viel'::text,'Irgendwelche'::text,'Viele Büroangestellte bleiben stehen, um seiner Gitarre zuzuhören.'::text),
(298105,33123,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... офісних працівників зупиняються, щоб послухати його гітару.'::text,'Багато'::text,'Багато'::text,'Будь-які'::text,'Багато офісних працівників зупиняються, щоб послухати його гітару.'::text),
(298104,33123,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... oficinistas se paran a escuchar su guitarra.'::text,'Muchos'::text,'Mucho'::text,'Cualquier'::text,'Muchos oficinistas se paran a escuchar su guitarra.'::text),
(298103,33123,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... employés de bureau s''arrêtent pour écouter sa guitare.'::text,'Beaucoup d'''::text,'Beaucoup d'''::text,'N''importe quels'::text,'Beaucoup d'' employés de bureau s''arrêtent pour écouter sa guitare.'::text),
(298106,33123,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ofis çalışanı onun gitarını dinlemek için duruyor.'::text,'Çok'::text,'Çok'::text,'Herhangi bir'::text,'Çok ofis çalışanı onun gitarını dinlemek için duruyor.'::text),
(298107,33123,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... irodista megáll, hogy meghallgassa a gitárját.'::text,'Sok'::text,'Sok'::text,'Bármilyen'::text,'Sok irodista megáll, hogy meghallgassa a gitárját.'::text),
(316020,35114,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Stopp! ... schwere Arm auf meiner Schulter ruiniert mein Leben!'::text,'Dieser'::text,'Diese'::text,'Jene'::text,'Stopp! Dieser schwere Arm auf meiner Schulter ruiniert mein Leben!'::text),
(316024,35114,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стоп! ... важка рука на моєму плечі руйнує мені життя!'::text,'Ця'::text,'Ці'::text,'Ті'::text,'Стоп! Ця важка рука на моєму плечі руйнує мені життя!'::text),
(316023,35114,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para! ¡... brazo pesado en mi hombro me está arruinando la vida!'::text,'Este'::text,'Estos'::text,'Esos'::text,'¡Para! ¡Este brazo pesado en mi hombro me está arruinando la vida!'::text),
(316022,35114,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Stop ! ... bras lourd sur mon épaule me gâche la vie !'::text,'Ce'::text,'Ces'::text,'Ces'::text,'Stop ! Ce bras lourd sur mon épaule me gâche la vie !'::text),
(316025,35114,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dur! Omzumdaki ... ağır kol hayatımı mahvediyor!'::text,'bu'::text,'bu'::text,'şu'::text,'Dur! Omzumdaki bu ağır kol hayatımı mahvediyor!'::text),
(316026,35114,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Állj! ... a nehéz kar a vállamon tönkreteszi az életemet!'::text,'Ez'::text,'Ezek'::text,'Azok'::text,'Állj! Ez a nehéz kar a vállamon tönkreteszi az életemet!'::text),
(316029,35115,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie legt ... Arm um die Schulter ihrer Freundin.'::text,'ihren'::text,'seinen'::text,'seinen'::text,'Sie legt ihren Arm um die Schulter ihrer Freundin.'::text),
(316033,35115,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона кладе ... руку на плече подруги.'::text,'свою'::text,'свою'::text,'свою'::text,'Вона кладе свою руку на плече подруги.'::text),
(316032,35115,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pone ... brazo sobre el hombro de su amiga.'::text,'su'::text,'su'::text,'su'::text,'Pone su brazo sobre el hombro de su amiga.'::text),
(316031,35115,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle passe ... bras autour de l''épaule de son amie.'::text,'son'::text,'son'::text,'son'::text,'Elle passe son bras autour de l''épaule de son amie.'::text),
(316034,35115,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... kolunu arkadaşının omzuna atıyor.'::text,'Onun'::text,'Onun'::text,'Onun'::text,'Onun kolunu arkadaşının omzuna atıyor.'::text),
(316035,35115,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Átteszi a ... a barátnője vállán.'::text,'karját'::text,'karját'::text,'karját'::text,'Átteszi a karját a barátnője vállán.'::text),
(316038,35116,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ist seine Hand? Auf der Schulter seines Freundes.'::text,'Wo'::text,'Was'::text,'Wer'::text,'Wo ist seine Hand? Auf der Schulter seines Freundes.'::text),
(316042,35116,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... його рука? На плечі його друга.'::text,'Де'::text,'Що'::text,'Хто'::text,'Де його рука? На плечі його друга.'::text),
(316041,35116,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... está su mano? En el hombro de su amigo.'::text,'Dónde'::text,'Qué'::text,'Quién'::text,'¿Dónde está su mano? En el hombro de su amigo.'::text),
(316040,35116,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... est sa main ? Sur l''épaule de son ami.'::text,'Où'::text,'Quoi'::text,'Qui'::text,'Où est sa main ? Sur l''épaule de son ami.'::text),
(316043,35116,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eli ...? Arkadaşının omzunda.'::text,'nerede'::text,'ne'::text,'kim'::text,'Eli nerede? Arkadaşının omzunda.'::text),
(316044,35116,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... van a keze? A barátja vállán.'::text,'Hol'::text,'Mi'::text,'Ki'::text,'Hol van a keze? A barátja vállán.'::text),
(316047,35117,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Freunde stehen ... einer Reihe, Arm über Schulter.'::text,'in'::text,'auf'::text,'an'::text,'Die Freunde stehen in einer Reihe, Arm über Schulter.'::text),
(316051,35117,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Друзі стоять ... ряд, рука на плечі.'::text,'в'::text,'на'::text,'біля'::text,'Друзі стоять в ряд, рука на плечі.'::text),
(316050,35117,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los amigos están ... fila, brazo sobre hombro.'::text,'en'::text,'sobre'::text,'a'::text,'Los amigos están en fila, brazo sobre hombro.'::text),
(316049,35117,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les amis se tiennent ... ligne, le bras sur l''épaule.'::text,'en'::text,'sur'::text,'à'::text,'Les amis se tiennent en ligne, le bras sur l''épaule.'::text),
(316052,35117,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Arkadaşlar kolları omuzlarda, bir sıra ... duruyor.'::text,''::text,'üstünde'::text,NULL::text,'Arkadaşlar kolları omuzlarda, bir sıra duruyor.'::text),
(316053,35117,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A barátok ... állnak, kar a vállon.'::text,'sorban'::text,'soron'::text,'sornál'::text,'A barátok sorban állnak, kar a vállon.'::text),
(316074,35120,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sonst gehen sie allein, aber gestern ... sie Arm auf Schulter.'::text,'gingen'::text,'gehen'::text,NULL::text,'Sonst gehen sie allein, aber gestern gingen sie Arm auf Schulter.'::text),
(316078,35120,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай вони ходять самі, але вчора ... рука на плечі.'::text,'йшли'::text,'ходять'::text,NULL::text,'Зазвичай вони ходять самі, але вчора йшли рука на плечі.'::text),
(316077,35120,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente caminan solos, pero ayer ... brazo sobre hombro.'::text,'caminaron'::text,'caminan'::text,NULL::text,'Normalmente caminan solos, pero ayer caminaron brazo sobre hombro.'::text),
(316076,35120,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude ils marchent seuls, mais hier ils ... bras dessus, bras dessous.'::text,'ont marché'::text,'marchent'::text,NULL::text,'D''habitude ils marchent seuls, mais hier ils ont marché bras dessus, bras dessous.'::text),
(316079,35120,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde yalnız yürürler ama dün kol kola ...'::text,'yürüdüler'::text,'yürürler'::text,NULL::text,'Genelde yalnız yürürler ama dün kol kola yürüdüler.'::text),
(316080,35120,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában egyedül sétálnak, de tegnap kart karba öltve ...'::text,'sétáltak'::text,'sétálnak'::text,NULL::text,'Általában egyedül sétálnak, de tegnap kart karba öltve sétáltak.'::text),
(316083,35121,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Fünf Freunde ... sich auf meine arme Schulter!'::text,'stützen'::text,'stützen'::text,'stützen'::text,'Katastrophe! Fünf Freunde stützen sich auf meine arme Schulter!'::text),
(316087,35121,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! П''ятеро друзів ... на моє бідне плече!'::text,'спираються'::text,'спираються'::text,'спираються'::text,'Катастрофа! П''ятеро друзів спираються на моє бідне плече!'::text),
(316086,35121,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Desastre! ¡Cinco amigos ... en mi pobre hombro!'::text,'se están apoyando'::text,'se apoyan'::text,'se están apoyando'::text,'¡Desastre! ¡Cinco amigos se están apoyando en mi pobre hombro!'::text),
(316085,35121,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! Cinq amis ... sur ma pauvre épaule !'::text,'sont en train de s''appuyer'::text,'s''appuient'::text,'sont en train de s''appuyer'::text,'Catastrophe ! Cinq amis sont en train de s''appuyer sur ma pauvre épaule !'::text),
(316088,35121,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Beş arkadaş zavallı omzuma ...!'::text,'yaslanıyor'::text,'yaslanır'::text,'yaslanıyor'::text,'Felaket! Beş arkadaş zavallı omzuma yaslanıyor!'::text),
(316089,35121,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! Öt barát ... a szegény vállamra!'::text,'támaszkodik'::text,'támaszkodik'::text,'támaszkodik'::text,'Katasztrófa! Öt barát támaszkodik a szegény vállamra!'::text),
(315795,35089,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Toller Freund, klar: „Ich ... nicht auf dich schießen“, sagt er.'::text,'werde'::text,'bin'::text,NULL::text,'Toller Freund, klar: „Ich werde nicht auf dich schießen“, sagt er.'::text),
(315799,35089,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудовий друг, звісно: «Я не ... в тебе стріляти», — каже він.'::text,'буду'::text,'є'::text,NULL::text,'Чудовий друг, звісно: «Я не буду в тебе стріляти», — каже він.'::text),
(315798,35089,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Qué gran amigo, claro: «Yo no ...», dice.'::text,'te dispararé'::text,'estoy'::text,NULL::text,'Qué gran amigo, claro: «Yo no te dispararé», dice.'::text),
(315797,35089,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super pote, évidemment : « Je ne ... pas dessus », dit-il.'::text,'te tirerai'::text,'suis'::text,NULL::text,'Super pote, évidemment : « Je ne te tirerai pas dessus », dit-il.'::text),
(315800,35089,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika arkadaş tabii: “Sana ateş ...”, diyor.'::text,'etmeyeceğim'::text,NULL::text,NULL::text,'Harika arkadaş tabii: “Sana ateş etmeyeceğim”, diyor.'::text),
(315801,35089,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyszerű barát, nyilván: „Nem ... rád lőni” – mondja.'::text,'fogok'::text,'vagyok'::text,NULL::text,'Nagyszerű barát, nyilván: „Nem fogok rád lőni” – mondja.'::text),
(315804,35090,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der rote Spieler hat einen Plan. Er ... hinter der Barriere hervor schießen.'::text,'wird'::text,'wird'::text,'wird'::text,'Der rote Spieler hat einen Plan. Er wird hinter der Barriere hervor schießen.'::text),
(315808,35090,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Червоний гравець має план. Він ... з-за барикади.'::text,'збирається вистрілити'::text,'вистрілить'::text,'збирається вистрілити'::text,'Червоний гравець має план. Він збирається вистрілити з-за барикади.'::text),
(315807,35090,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El jugador rojo tiene un plan. ... desde la barrera.'::text,'Va a disparar'::text,'Disparará'::text,'Va a disparar'::text,'El jugador rojo tiene un plan. Va a disparar desde la barrera.'::text),
(315806,35090,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le joueur rouge a un plan. Il ... depuis la barrière.'::text,'va tirer'::text,'tirera'::text,'va tirer'::text,'Le joueur rouge a un plan. Il va tirer depuis la barrière.'::text),
(315809,35090,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kırmızı oyuncunun bir planı var. Bariyerin arkasından ...'::text,'ateş edecek'::text,'ateş edecek'::text,'ateş edecek'::text,'Kırmızı oyuncunun bir planı var. Bariyerin arkasından ateş edecek.'::text),
(315810,35090,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A piros játékosnak van egy terve. A barikád mögül ... lőni.'::text,'fog'::text,'fog'::text,'fog'::text,'A piros játékosnak van egy terve. A barikád mögül fog lőni.'::text),
(315813,35091,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der rote Spieler lehnt sich raus und zielt. Er ... schießen.'::text,'wird'::text,'wird'::text,NULL::text,'Der rote Spieler lehnt sich raus und zielt. Er wird schießen.'::text),
(315817,35091,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Червоний гравець вихиляється й цілиться. Він ...'::text,'збирається вистрілити'::text,'вистрілить'::text,NULL::text,'Червоний гравець вихиляється й цілиться. Він збирається вистрілити.'::text),
(315816,35091,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El jugador rojo se asoma y apunta. ... disparar.'::text,'Va a'::text,NULL::text,NULL::text,'El jugador rojo se asoma y apunta. Va a disparar.'::text),
(315815,35091,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le joueur rouge se penche et vise. Il ... tirer.'::text,'va'::text,NULL::text,NULL::text,'Le joueur rouge se penche et vise. Il va tirer.'::text),
(315818,35091,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kırmızı oyuncu dışarı eğilip nişan alıyor. ...'::text,'Ateş edecek'::text,'Ateş edecek'::text,NULL::text,'Kırmızı oyuncu dışarı eğilip nişan alıyor. Ateş edecek.'::text),
(315819,35091,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A piros játékos kihajol és céloz. ... lőni.'::text,'Fog'::text,'Fog'::text,NULL::text,'A piros játékos kihajol és céloz. Fog lőni.'::text),
(315822,35092,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, er hat mir die Spielregel gesagt: Du ... hinter Barrieren hervor schießen.'::text,'musst'::text,'musst'::text,'solltest'::text,'Hör zu, er hat mir die Spielregel gesagt: Du musst hinter Barrieren hervor schießen.'::text),
(315826,35092,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, він сказав мені правило гри: ти ... стріляти з-за барикад.'::text,'маєш'::text,'мусиш'::text,'мав би'::text,'Слухай, він сказав мені правило гри: ти маєш стріляти з-за барикад.'::text),
(315825,35092,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me dijo la regla del juego: ... disparar desde detrás de las barreras.'::text,'tienes que'::text,'debes'::text,'deberías'::text,'Oye, me dijo la regla del juego: tienes que disparar desde detrás de las barreras.'::text),
(315824,35092,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, il m''a dit la règle du jeu : tu ... tirer depuis derrière les barrières.'::text,'dois'::text,'dois'::text,'devrais'::text,'Écoute, il m''a dit la règle du jeu : tu dois tirer depuis derrière les barrières.'::text),
(315827,35092,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana oyunun kuralını söyledi: bariyerlerin arkasından ...'::text,'ateş etmek zorundasın'::text,'ateş etmelisin'::text,'ateş etmelisin'::text,'Dinle, bana oyunun kuralını söyledi: bariyerlerin arkasından ateş etmek zorundasın.'::text),
(315828,35092,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, elmondta a játékszabályt: a barikádok mögül ... lőnöd.'::text,'kell'::text,'kell'::text,'kellene'::text,'Figyelj, elmondta a játékszabályt: a barikádok mögül kell lőnöd.'::text),
(315831,35093,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mädel, der blaue Typ hat mir gesagt, dass er nächstes Mal zuerst schießen ...'::text,'sollte'::text,'sollte'::text,'sollte'::text,'Mädel, der blaue Typ hat mir gesagt, dass er nächstes Mal zuerst schießen sollte.'::text),
(315835,35093,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, синій хлопець сказав мені, що наступного разу він ... стріляти першим.'::text,'мав би'::text,'мав би'::text,'мав би'::text,'Подруго, синій хлопець сказав мені, що наступного разу він мав би стріляти першим.'::text),
(315834,35093,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, el chico azul me dijo que la próxima vez ... disparar primero.'::text,'debería'::text,'debería'::text,'debería'::text,'Tía, el chico azul me dijo que la próxima vez debería disparar primero.'::text),
(315833,35093,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meuf, le gars en bleu m''a dit qu''il ... tirer en premier la prochaine fois.'::text,'devrait'::text,'devrait'::text,'devrait'::text,'Meuf, le gars en bleu m''a dit qu''il devrait tirer en premier la prochaine fois.'::text),
(315836,35093,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, mavi çocuk bana dedi ki bir dahaki sefere önce o ...'::text,'ateş etmeli'::text,'ateş etmeli'::text,'ateş etmeli'::text,'Kızım, mavi çocuk bana dedi ki bir dahaki sefere önce o ateş etmeli.'::text),
(315837,35093,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, a kék srác azt mondta, hogy legközelebb neki ... elsőként lőnie.'::text,'kellene'::text,'kellene'::text,'kellene'::text,'Csajszi, a kék srác azt mondta, hogy legközelebb neki kellene elsőként lőnie.'::text),
(315840,35094,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Stell dir vor, ich hab gehört, er hat zuerst geschossen, ... hat der blaue Typ verloren.'::text,'also'::text,'aber'::text,'weil'::text,'Stell dir vor, ich hab gehört, er hat zuerst geschossen, also hat der blaue Typ verloren.'::text),
(315844,35094,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, я чула, що він вистрілив першим, ... синій хлопець програв.'::text,'тому'::text,'але'::text,'бо'::text,'Уяви, я чула, що він вистрілив першим, тому синій хлопець програв.'::text),
(315843,35094,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿Sabes qué? Me han dicho que disparó primero, ... el chico azul perdió.'::text,'así que'::text,'pero'::text,'porque'::text,'¿Sabes qué? Me han dicho que disparó primero, así que el chico azul perdió.'::text),
(315842,35094,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, j''ai entendu qu''il a tiré le premier, ... le gars en bleu a perdu.'::text,'donc'::text,'mais'::text,'parce que'::text,'Devine quoi, j''ai entendu qu''il a tiré le premier, donc le gars en bleu a perdu.'::text),
(315845,35094,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım ne oldu, duydum ki ilk o ateş etmiş ... mavi çocuk kaybetmiş.'::text,'bu yüzden'::text,'ama'::text,'çünkü'::text,'Bil bakalım ne oldu, duydum ki ilk o ateş etmiş bu yüzden mavi çocuk kaybetmiş.'::text),
(315846,35094,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, azt hallottam, hogy ő lőtt először, ... a kék srác vesztett.'::text,'ezért'::text,'de'::text,'mert'::text,'Képzeld, azt hallottam, hogy ő lőtt először, ezért a kék srác vesztett.'::text),
(300468,33386,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Gastgeber ... eine Weste und ein Hemd.'::text,'hat'::text,'haben'::text,'hat'::text,'Der Gastgeber hat eine Weste und ein Hemd.'::text),
(300472,33386,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Господар ... жилет і сорочку.'::text,'має'::text,'мати'::text,'має'::text,'Господар має жилет і сорочку.'::text),
(300471,33386,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El anfitrión ... un chaleco y una camisa.'::text,'tiene'::text,'tienen'::text,'tiene'::text,'El anfitrión tiene un chaleco y una camisa.'::text),
(300470,33386,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''hôte ... un gilet et une chemise.'::text,'a'::text,'ont'::text,'a'::text,'L''hôte a un gilet et une chemise.'::text),
(300473,33386,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ev sahibinin bir yeleği ve bir gömleği ...'::text,'var'::text,'var'::text,'var'::text,'Ev sahibinin bir yeleği ve bir gömleği var.'::text),
(300474,33386,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A házigazdának ... egy mellénye és egy inge.'::text,'van'::text,'van'::text,'van'::text,'A házigazdának van egy mellénye és egy inge.'::text),
(300486,33388,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, der Gastgeber schiebt gleich ... Gläser Wasser rüber.'::text,'zwei'::text,'zweite'::text,'zweimal'::text,'Yo, der Gastgeber schiebt gleich zwei Gläser Wasser rüber.'::text),
(300490,33388,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, господар зараз підсуне ... склянки води.'::text,'дві'::text,'другі'::text,'двічі'::text,'Йо, господар зараз підсуне дві склянки води.'::text),
(300489,33388,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, el anfitrión va a pasar ... vasos de agua.'::text,'dos'::text,'segundos'::text,'dos veces'::text,'Tío, el anfitrión va a pasar dos vasos de agua.'::text),
(300488,33388,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, l''hôte va faire glisser ... verres d''eau.'::text,'deux'::text,'deuxièmes'::text,'deux fois'::text,'Wesh, l''hôte va faire glisser deux verres d''eau.'::text),
(300491,33388,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ev sahibi şimdi ... bardak su kaydıracak.'::text,'iki'::text,'ikinci'::text,'iki kez'::text,'Kanka, ev sahibi şimdi iki bardak su kaydıracak.'::text),
(300492,33388,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a házigazda mindjárt odacsúsztat ... pohár vizet.'::text,'két'::text,'második'::text,'kétszer'::text,'Tesó, a házigazda mindjárt odacsúsztat két pohár vizet.'::text),
(300495,33389,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, der Gastgeber hat so viel ... auf dem Tisch, kein Witz.'::text,'Essen'::text,'Essen'::text,'Mahlzeiten'::text,'Digga, der Gastgeber hat so viel Essen auf dem Tisch, kein Witz.'::text),
(300499,33389,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, у господаря стільки ... на тому столі, без брехні.'::text,'їжі'::text,'їжі'::text,'страв'::text,'Бро, у господаря стільки їжі на тому столі, без брехні.'::text),
(300498,33389,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, el anfitrión tiene tanta ... en esa mesa, en serio.'::text,'comida'::text,'comida'::text,'platos'::text,'Tío, el anfitrión tiene tanta comida en esa mesa, en serio.'::text),
(300497,33389,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, l''hôte a tellement de ... sur cette table, sans mentir.'::text,'nourriture'::text,'nourriture'::text,'repas'::text,'Frérot, l''hôte a tellement de nourriture sur cette table, sans mentir.'::text),
(300500,33389,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, ev sahibinin o masada o kadar çok ... var ki, yemin ederim.'::text,'yemeği'::text,'yemekleri'::text,'öğünleri'::text,'Kanka, ev sahibinin o masada o kadar çok yemeği var ki, yemin ederim.'::text),
(300501,33389,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a házigazdának annyi ... van azon az asztalon, komolyan.'::text,'kajája'::text,'kajája'::text,'fogása'::text,'Tesó, a házigazdának annyi kajája van azon az asztalon, komolyan.'::text),
(300504,33390,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Gastgeber hat ein Budget von 30 Euro und ... Brötchen.'::text,'einige'::text,'viel'::text,'irgendwelche'::text,'Der Gastgeber hat ein Budget von 30 Euro und einige Brötchen.'::text),
(300508,33390,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У господаря бюджет 30 євро і ... булочки.'::text,'кілька'::text,'багато'::text,'будь-які'::text,'У господаря бюджет 30 євро і кілька булочки.'::text),
(300507,33390,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El anfitrión tiene un presupuesto de 30 euros y ... panecillos.'::text,'algunos'::text,'mucho'::text,'cualquier'::text,'El anfitrión tiene un presupuesto de 30 euros y algunos panecillos.'::text),
(300506,33390,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''hôte a un budget de 30 euros et ... petits pains.'::text,'des'::text,'beaucoup de'::text,'n''importe quels'::text,'L''hôte a un budget de 30 euros et des petits pains.'::text),
(300509,33390,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ev sahibinin 30 euroluk bir bütçesi ve ... küçük ekmeği var.'::text,'birkaç'::text,'çok'::text,'herhangi bir'::text,'Ev sahibinin 30 euroluk bir bütçesi ve birkaç küçük ekmeği var.'::text),
(300510,33390,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A házigazdának 30 eurós kerete és ... zsemléje van.'::text,'néhány'::text,'sok'::text,'bármilyen'::text,'A házigazdának 30 eurós kerete és néhány zsemléje van.'::text),
(300522,33392,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Gäste haben Hunger, also ... der Gastgeber die Pasta bringen.'::text,'sollte'::text,'sollte'::text,'soll'::text,'Die Gäste haben Hunger, also sollte der Gastgeber die Pasta bringen.'::text),
(300526,33392,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Гості голодні, тож господар ... принести пасту.'::text,'мав би'::text,'мав би'::text,'буде'::text,'Гості голодні, тож господар мав би принести пасту.'::text),
(300525,33392,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los invitados tienen hambre, así que el anfitrión ... traer la pasta.'::text,'debería'::text,'debería'::text,'deberá'::text,'Los invitados tienen hambre, así que el anfitrión debería traer la pasta.'::text),
(300524,33392,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les invités ont faim, donc l''hôte ... apporter les pâtes.'::text,'devrait'::text,'devrait'::text,'devra'::text,'Les invités ont faim, donc l''hôte devrait apporter les pâtes.'::text),
(300527,33392,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Misafirler aç, bu yüzden ev sahibi makarnayı ...'::text,'getirmeli'::text,'getirmeli'::text,'getirecek'::text,'Misafirler aç, bu yüzden ev sahibi makarnayı getirmeli.'::text),
(300528,33392,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A vendégek éhesek, ezért a házigazdának ... behoznia a tésztát.'::text,'kellene'::text,'kellene'::text,'kell'::text,'A vendégek éhesek, ezért a házigazdának kellene behoznia a tésztát.'::text),
(300531,33393,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Gastgeber ist glücklich, ... seine Gäste lachen.'::text,'weil'::text,'aber'::text,'also'::text,'Der Gastgeber ist glücklich, weil seine Gäste lachen.'::text),
(300535,33393,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Господар щасливий, ... його гості сміються.'::text,'бо'::text,'але'::text,'тому'::text,'Господар щасливий, бо його гості сміються.'::text),
(300534,33393,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El anfitrión está feliz ... sus invitados se están riendo.'::text,'porque'::text,'pero'::text,'así que'::text,'El anfitrión está feliz porque sus invitados se están riendo.'::text),
(300533,33393,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''hôte est content ... ses invités rient.'::text,'parce que'::text,'mais'::text,'donc'::text,'L''hôte est content parce que ses invités rient.'::text),
(300536,33393,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ev sahibi mutlu ... misafirleri gülüyor.'::text,'çünkü'::text,'ama'::text,'bu yüzden'::text,'Ev sahibi mutlu çünkü misafirleri gülüyor.'::text),
(300537,33393,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A házigazda boldog, ... a vendégei nevetnek.'::text,'mert'::text,'de'::text,'ezért'::text,'A házigazda boldog, mert a vendégei nevetnek.'::text),
(314796,34978,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Digga, ... setzt sie uns hin? Neben die Kerze?'::text,'Wohin'::text,'Wer'::text,'Was'::text,'Digga, Wohin setzt sie uns hin? Neben die Kerze?'::text),
(314800,34978,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, ... вона нас посадить? Біля свічки?'::text,'Куди'::text,'Хто'::text,'Що'::text,'Бро, Куди вона нас посадить? Біля свічки?'::text),
(314799,34978,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ¿... nos va a sentar? ¿Junto a la vela?'::text,'dónde'::text,'quién'::text,'qué'::text,'Tío, ¿dónde nos va a sentar? ¿Junto a la vela?'::text),
(314798,34978,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, ... est-ce qu''elle va nous placer ? Près de la bougie ?'::text,'où'::text,'qui'::text,'que'::text,'Frérot, où est-ce qu''elle va nous placer ? Près de la bougie ?'::text),
(314801,34978,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bizi ... oturtacak? Mumun yanına mı?'::text,'nereye'::text,'kim'::text,'ne'::text,'Kanka, bizi nereye oturtacak? Mumun yanına mı?'::text),
(314802,34978,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... fog leültetni minket? A gyertya mellé?'::text,'hová'::text,'ki'::text,'mi'::text,'Tesó, hová fog leültetni minket? A gyertya mellé?'::text),
(314814,34980,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie platziert jeden Abend Gäste, also ... sie gestern Abend auch Gäste.'::text,'platzierte'::text,'platziert'::text,NULL::text,'Sie platziert jeden Abend Gäste, also platzierte sie gestern Abend auch Gäste.'::text),
(314818,34980,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона щовечора садить гостей, тож учора ввечері вона теж ... гостей.'::text,'садила'::text,'садить'::text,NULL::text,'Вона щовечора садить гостей, тож учора ввечері вона теж садила гостей.'::text),
(314817,34980,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sienta a clientes todas las noches, así que anoche también ... a clientes.'::text,'sentó'::text,'sienta'::text,NULL::text,'Sienta a clientes todas las noches, así que anoche también sentó a clientes.'::text),
(314816,34980,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle place des clients tous les soirs, donc hier soir elle ... aussi des clients.'::text,'a placé'::text,'place'::text,NULL::text,'Elle place des clients tous les soirs, donc hier soir elle a placé aussi des clients.'::text),
(314819,34980,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Her akşam misafirleri yerlerine oturtur, bu yüzden dün akşam da misafirleri ...'::text,'oturttu'::text,'oturtur'::text,NULL::text,'Her akşam misafirleri yerlerine oturtur, bu yüzden dün akşam da misafirleri oturttu.'::text),
(314820,34980,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden este vendégeket ültet le, így tegnap este is ... vendégeket.'::text,'leültetett'::text,'leültet'::text,NULL::text,'Minden este vendégeket ültet le, így tegnap este is leültetett vendégeket.'::text),
(314823,34981,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Absolut unfassbar! Sie ... sie gerade an den besten Tisch!'::text,'setzt'::text,'setzt'::text,'setzt'::text,'Absolut unfassbar! Sie setzt sie gerade an den besten Tisch!'::text),
(314827,34981,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Просто неймовірно! Вона саме зараз ... їх за найкращий столик!'::text,'садить'::text,'садить'::text,'садить'::text,'Просто неймовірно! Вона саме зараз садить їх за найкращий столик!'::text),
(314826,34981,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Absolutamente increíble! ¡Los ... en la mejor mesa ahora mismo!'::text,'está sentando'::text,'sienta'::text,'está sentando'::text,'¡Absolutamente increíble! ¡Los está sentando en la mejor mesa ahora mismo!'::text),
(314825,34981,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Absolument incroyable ! Elle ... en ce moment à la meilleure table !'::text,'est en train de les placer'::text,'les place'::text,'est en train de les placer'::text,'Absolument incroyable ! Elle est en train de les placer en ce moment à la meilleure table !'::text),
(314828,34981,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İnanılmaz! Onları şu an en iyi masaya ...!'::text,'oturtuyor'::text,'oturtur'::text,'oturtuyor'::text,'İnanılmaz! Onları şu an en iyi masaya oturtuyor!'::text),
(314829,34981,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hihetetlen! Épp most ... őket a legjobb asztalhoz!'::text,'ülteti'::text,'ülteti'::text,'ülteti'::text,'Hihetetlen! Épp most ülteti őket a legjobb asztalhoz!'::text),
(314832,34982,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sonst platziert sie große Gruppen, aber jetzt ... sie ein Paar.'::text,'platziert'::text,'platziert'::text,NULL::text,'Sonst platziert sie große Gruppen, aber jetzt platziert sie ein Paar.'::text),
(314836,34982,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Зазвичай вона садить великі компанії, але зараз ... пару.'::text,'садить'::text,'садить'::text,NULL::text,'Зазвичай вона садить великі компанії, але зараз садить пару.'::text),
(314835,34982,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Normalmente sienta a grupos grandes, pero ahora ... a una pareja.'::text,'está sentando'::text,'sienta'::text,NULL::text,'Normalmente sienta a grupos grandes, pero ahora está sentando a una pareja.'::text),
(314834,34982,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''habitude elle place de grands groupes, mais maintenant elle ... un couple.'::text,'est en train de placer'::text,'place'::text,NULL::text,'D''habitude elle place de grands groupes, mais maintenant elle est en train de placer un couple.'::text),
(314837,34982,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genelde büyük grupları oturtur ama şimdi bir çifti ...'::text,'oturtuyor'::text,'oturtur'::text,NULL::text,'Genelde büyük grupları oturtur ama şimdi bir çifti oturtuyor.'::text),
(314838,34982,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Általában nagy csoportokat ültet le, de most egy párt ...'::text,'ültet le'::text,'ültet le'::text,NULL::text,'Általában nagy csoportokat ültet le, de most egy párt ültet le.'::text),
(314841,34983,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Paar wartet. Die Kellnerin ... sie in einer Minute platzieren.'::text,'wird'::text,'platziert'::text,'platzierte'::text,'Das Paar wartet. Die Kellnerin wird sie in einer Minute platzieren.'::text),
(314845,34983,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пара чекає. Офіціантка ... їх за хвилину.'::text,'посадить'::text,'садить'::text,'посадила'::text,'Пара чекає. Офіціантка посадить їх за хвилину.'::text),
(314844,34983,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La pareja espera. La camarera los ... en un minuto.'::text,'sentará'::text,'sienta'::text,'sentó'::text,'La pareja espera. La camarera los sentará en un minuto.'::text),
(314843,34983,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le couple attend. La serveuse les ... dans une minute.'::text,'placera'::text,'place'::text,'a placés'::text,'Le couple attend. La serveuse les placera dans une minute.'::text),
(314846,34983,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çift bekliyor. Garson kız onları bir dakika içinde ...'::text,'oturtacak'::text,'oturtur'::text,'oturttu'::text,'Çift bekliyor. Garson kız onları bir dakika içinde oturtacak.'::text),
(314847,34983,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pár vár. A pincérnő egy perc múlva ... őket.'::text,'le fogja ültetni'::text,'leülteti'::text,'leültette'::text,'A pár vár. A pincérnő egy perc múlva le fogja ültetni őket.'::text),
(314850,34984,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sehr fair, klar: Sie ... das nächste Paar an die Küchentür setzen.'::text,'wird'::text,'wird'::text,'wird'::text,'Sehr fair, klar: Sie wird das nächste Paar an die Küchentür setzen.'::text),
(314854,34984,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Дуже чесно, звісно: вона ... наступну пару біля дверей на кухню.'::text,'збирається посадити'::text,'посадить'::text,'збирається посадити'::text,'Дуже чесно, звісно: вона збирається посадити наступну пару біля дверей на кухню.'::text),
(314853,34984,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Muy justo, claro: ... a la siguiente pareja junto a la puerta de la cocina.'::text,'va a sentar'::text,'sentará'::text,'va a sentar'::text,'Muy justo, claro: va a sentar a la siguiente pareja junto a la puerta de la cocina.'::text),
(314852,34984,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Très juste, évidemment : elle ... le couple suivant près de la porte de la cuisine.'::text,'va placer'::text,'placera'::text,'va placer'::text,'Très juste, évidemment : elle va placer le couple suivant près de la porte de la cuisine.'::text),
(314855,34984,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çok adil, tabii: sonraki çifti mutfak kapısının yanına ...'::text,'oturtacak'::text,'oturtacak'::text,'oturtacak'::text,'Çok adil, tabii: sonraki çifti mutfak kapısının yanına oturtacak.'::text),
(314856,34984,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nagyon igazságos, persze: a következő párt a konyhaajtó mellé ... ültetni.'::text,'fogja'::text,'fogja'::text,'fogja'::text,'Nagyon igazságos, persze: a következő párt a konyhaajtó mellé fogja ültetni.'::text),
(303123,33681,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Anwältin ... die Aktentasche mit beiden Händen heben.'::text,'kann'::text,'kann'::text,'kann'::text,'Die Anwältin kann die Aktentasche mit beiden Händen heben.'::text),
(303127,33681,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Юристка ... підняти портфель обома руками.'::text,'може'::text,'може'::text,'може'::text,'Юристка може підняти портфель обома руками.'::text),
(303126,33681,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La abogada ... levantar el maletín con las dos manos.'::text,'puede'::text,'puede'::text,'puede'::text,'La abogada puede levantar el maletín con las dos manos.'::text),
(303125,33681,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''avocate ... soulever la mallette à deux mains.'::text,'peut'::text,'peut'::text,'peut'::text,'L''avocate peut soulever la mallette à deux mains.'::text),
(303128,33681,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avukat evrak çantasını iki eliyle ...'::text,'kaldırabilir'::text,'kaldırabilir'::text,'kaldırabilir'::text,'Avukat evrak çantasını iki eliyle kaldırabilir.'::text),
(303129,33681,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ügyvédnő két kézzel ... felemelni az aktatáskát.'::text,'tudja'::text,'tudja'::text,'tudja'::text,'Az ügyvédnő két kézzel tudja felemelni az aktatáskát.'::text),
(303132,33682,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Anwältin hat einen Stapel dicker ...'::text,'Bücher.'::text,'Buch.'::text,'Bücher.'::text,'Die Anwältin hat einen Stapel dicker Bücher.'::text),
(303136,33682,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Юристка має стос товстих ...'::text,'книжок.'::text,'книжка.'::text,'книжок.'::text,'Юристка має стос товстих книжок.'::text),
(303135,33682,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La abogada tiene un montón de ... gordos.'::text,'libros'::text,'libro'::text,'libros'::text,'La abogada tiene un montón de libros gordos.'::text),
(303134,33682,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''avocate a une pile de ... épais.'::text,'livres'::text,'livre'::text,'livres'::text,'L''avocate a une pile de livres épais.'::text),
(303137,33682,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avukatın bir yığın kalın ... var.'::text,'kitabı'::text,'kitabı'::text,'kitabı'::text,'Avukatın bir yığın kalın kitabı var.'::text),
(303138,33682,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ügyvédnőnek van egy halom vastag ...'::text,'könyvei.'::text,'könyve.'::text,'könyvei.'::text,'Az ügyvédnőnek van egy halom vastag könyvei.'::text),
(303150,33684,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... Bücher sind dick, also liest die Anwältin dicke Bücher.'::text,'Diese'::text,'Dieses'::text,'Jenes'::text,'Diese Bücher sind dick, also liest die Anwältin dicke Bücher.'::text),
(303154,33684,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... книжки товсті, тож юристка читає товсті книжки.'::text,'Ці'::text,'Ця'::text,'Та'::text,'Ці книжки товсті, тож юристка читає товсті книжки.'::text),
(303153,33684,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... libros son gruesos, así que la abogada lee libros gruesos.'::text,'Estos'::text,'Este'::text,'Ese'::text,'Estos libros son gruesos, así que la abogada lee libros gruesos.'::text),
(303152,33684,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... livres sont épais, donc l''avocate lit des livres épais.'::text,'Ces'::text,'Ce'::text,'Ce'::text,'Ces livres sont épais, donc l''avocate lit des livres épais.'::text),
(303155,33684,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... kitaplar kalın, bu yüzden avukat kalın kitaplar okuyor.'::text,'Bu'::text,'Bu'::text,'Şu'::text,'Bu kitaplar kalın, bu yüzden avukat kalın kitaplar okuyor.'::text),
(303156,33684,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... a könyvek vastagok, ezért az ügyvédnő vastag könyveket olvas.'::text,'Ezek'::text,'Ez'::text,'Az'::text,'Ezek a könyvek vastagok, ezért az ügyvédnő vastag könyveket olvas.'::text),
(303159,33685,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Niemals! Die Anwältin gibt ... Aktentasche nie aus der Hand!'::text,'ihre'::text,'seine'::text,'seine'::text,'Niemals! Die Anwältin gibt ihre Aktentasche nie aus der Hand!'::text),
(303163,33685,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніколи! Юристка ніколи не віддає ... портфель!'::text,'свій'::text,'свій'::text,'свій'::text,'Ніколи! Юристка ніколи не віддає свій портфель!'::text),
(303162,33685,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Jamás! ¡La abogada nunca suelta ... maletín!'::text,'su'::text,'su'::text,'su'::text,'¡Jamás! ¡La abogada nunca suelta su maletín!'::text),
(303161,33685,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jamais ! L''avocate ne lâche jamais ... mallette !'::text,'sa'::text,'sa'::text,'sa'::text,'Jamais ! L''avocate ne lâche jamais sa mallette !'::text),
(303164,33685,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Asla! Avukat ... evrak çantasını asla kimseye vermez!'::text,'onun'::text,'onun'::text,'onun'::text,'Asla! Avukat onun evrak çantasını asla kimseye vermez!'::text),
(303165,33685,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha! Az ügyvédnő soha nem adja ki a kezéből az ...!'::text,'aktatáskáját'::text,'aktatáskáját'::text,'aktatáskáját'::text,'Soha! Az ügyvédnő soha nem adja ki a kezéből az aktatáskáját!'::text),
(303168,33686,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... geht die Anwältin? Zum Gericht! Das ist das Ende!'::text,'Wohin'::text,'Wer'::text,'Was'::text,'Wohin geht die Anwältin? Zum Gericht! Das ist das Ende!'::text),
(303172,33686,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... йде юристка? До суду! Це кінець!'::text,'Куди'::text,'Хто'::text,'Що'::text,'Куди йде юристка? До суду! Це кінець!'::text),
(303171,33686,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¿... va la abogada? ¡Al juzgado! ¡Es el fin!'::text,'Adónde'::text,'Quién'::text,'Qué'::text,'¿Adónde va la abogada? ¡Al juzgado! ¡Es el fin!'::text),
(303170,33686,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... va l''avocate ? Au tribunal ! C''est la fin !'::text,'Où'::text,'Qui'::text,'Que'::text,'Où va l''avocate ? Au tribunal ! C''est la fin !'::text),
(303173,33686,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avukat ... gidiyor? Mahkemeye! Bu son!'::text,'nereye'::text,'kim'::text,'ne'::text,'Avukat nereye gidiyor? Mahkemeye! Bu son!'::text),
(303174,33686,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... megy az ügyvédnő? A bíróságra! Ez a vég!'::text,'Hová'::text,'Ki'::text,'Mi'::text,'Hová megy az ügyvédnő? A bíróságra! Ez a vég!'::text),
(303177,33687,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der große Fall der Anwältin ist ... Montag! Der schlimmste Tag!'::text,'am'::text,'im'::text,'um'::text,'Der große Fall der Anwältin ist am Montag! Der schlimmste Tag!'::text),
(303181,33687,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Велика справа юристки — ... понеділок! Найгірший день!'::text,'у'::text,'в'::text,'о'::text,'Велика справа юристки — у понеділок! Найгірший день!'::text),
(303180,33687,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El gran caso de la abogada es ... el lunes! ¡El peor día!'::text,''::text,'en'::text,'a'::text,'¡El gran caso de la abogada es el lunes! ¡El peor día!'::text),
(303179,33687,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le grand procès de l''avocate est ... lundi ! Le pire jour !'::text,''::text,'dans'::text,'à'::text,'Le grand procès de l''avocate est lundi ! Le pire jour !'::text),
(303182,33687,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avukatın büyük davası pazartesi ...! En kötü gün!'::text,''::text,NULL::text,NULL::text,'Avukatın büyük davası pazartesi! En kötü gün!'::text),
(303183,33687,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ügyvédnő nagy tárgyalása ... van! A legrosszabb nap!'::text,'hétfőn'::text,'hétfőben'::text,'hétfőkor'::text,'Az ügyvédnő nagy tárgyalása hétfőn van! A legrosszabb nap!'::text),
(303186,33688,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Anwältin hat ... Aktentasche und ein paar Papiere.'::text,'eine'::text,'erste'::text,'einmal'::text,'Die Anwältin hat eine Aktentasche und ein paar Papiere.'::text),
(303190,33688,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Юристка має ... портфель і якісь папери.'::text,'один'::text,'перший'::text,'один раз'::text,'Юристка має один портфель і якісь папери.'::text),
(303189,33688,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La abogada tiene ... maletín y algunos papeles.'::text,'un'::text,'primer'::text,'una vez'::text,'La abogada tiene un maletín y algunos papeles.'::text),
(303188,33688,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''avocate a ... mallette et quelques papiers.'::text,'une'::text,'première'::text,'une fois'::text,'L''avocate a une mallette et quelques papiers.'::text),
(303191,33688,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avukatın ... evrak çantası ve birkaç kâğıdı var.'::text,'bir'::text,'birinci'::text,'bir kez'::text,'Avukatın bir evrak çantası ve birkaç kâğıdı var.'::text),
(303192,33688,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az ügyvédnőnek ... aktatáskája és néhány papírja van.'::text,'egy'::text,'első'::text,'egyszer'::text,'Az ügyvédnőnek egy aktatáskája és néhány papírja van.'::text),
(297201,33023,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Student ... eine Eins, die beste Note in der Klasse.'::text,'bekam'::text,'bekommt'::text,'bekommen'::text,'Der Student bekam eine Eins, die beste Note in der Klasse.'::text),
(297205,33023,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Студент ... «відмінно», найкращу оцінку в групі.'::text,'отримав'::text,'отримує'::text,'отримати'::text,'Студент отримав «відмінно», найкращу оцінку в групі.'::text),
(297204,33023,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El estudiante ... un sobresaliente, la mejor nota de la clase.'::text,'sacó'::text,'saca'::text,'sacar'::text,'El estudiante sacó un sobresaliente, la mejor nota de la clase.'::text),
(297203,33023,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''étudiant ... un 20 sur 20, la meilleure note de la classe.'::text,'a eu'::text,'a'::text,'avoir'::text,'L''étudiant a eu un 20 sur 20, la meilleure note de la classe.'::text),
(297206,33023,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğrenci sınıftaki en iyi not olan A''yı ...'::text,'aldı'::text,'alır'::text,'almak'::text,'Öğrenci sınıftaki en iyi not olan A''yı aldı.'::text),
(297207,33023,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A diák ... egy ötöst, az osztály legjobb jegyét.'::text,'kapott'::text,'kap'::text,'kapni'::text,'A diák kapott egy ötöst, az osztály legjobb jegyét.'::text),
(297210,33024,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Seine Noten sind sonst eine Katastrophe, aber gestern ... er eine Eins!'::text,'bekam'::text,'bekommt'::text,NULL::text,'Seine Noten sind sonst eine Katastrophe, aber gestern bekam er eine Eins!'::text),
(297214,33024,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Його оцінки зазвичай катастрофа, але вчора він ... «відмінно»!'::text,'отримав'::text,'отримує'::text,NULL::text,'Його оцінки зазвичай катастрофа, але вчора він отримав «відмінно»!'::text),
(297213,33024,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Sus notas suelen ser un desastre, pero ayer ... un sobresaliente!'::text,'sacó'::text,'saca'::text,NULL::text,'¡Sus notas suelen ser un desastre, pero ayer sacó un sobresaliente!'::text),
(297212,33024,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ses notes sont d''habitude une catastrophe, mais hier il ... un 20 sur 20 !'::text,'a eu'::text,'a'::text,NULL::text,'Ses notes sont d''habitude une catastrophe, mais hier il a eu un 20 sur 20 !'::text),
(297215,33024,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Notları genelde felakettir ama dün A ...!'::text,'aldı'::text,'alır'::text,NULL::text,'Notları genelde felakettir ama dün A aldı!'::text),
(297216,33024,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A jegyei általában katasztrófák, de tegnap ... egy ötöst!'::text,'kapott'::text,'kap'::text,NULL::text,'A jegyei általában katasztrófák, de tegnap kapott egy ötöst!'::text),
(297219,33025,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Es ist eine Katastrophe! Er ... gerade Notizen für seine Note!'::text,'schreibt'::text,'schreibt'::text,'schreibend'::text,'Es ist eine Katastrophe! Er schreibt gerade Notizen für seine Note!'::text),
