(302415,33602,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ... como diez ollas en esta cocina, en serio.'::text,'hay'::text,'hay'::text,'hay'::text,'Tío, hay como diez ollas en esta cocina, en serio.'::text),
(302414,33602,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, ... genre dix casseroles dans cette cuisine, sans mentir.'::text,'il y a'::text,'il y a'::text,'il y a'::text,'Wesh, il y a genre dix casseroles dans cette cuisine, sans mentir.'::text),
(302417,33602,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu mutfakta on tane falan tencere ..., yemin ederim.'::text,'var'::text,'var'::text,'olmak'::text,'Kanka, bu mutfakta on tane falan tencere var, yemin ederim.'::text),
(302418,33602,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ... vagy tíz lábas ebben a konyhában, komolyan.'::text,'van'::text,'van'::text,'lenni'::text,'Tesó, van vagy tíz lábas ebben a konyhában, komolyan.'::text),
(302421,33603,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Küchenregel, Digga: Die Köchin ... die hohe Mütze tragen.'::text,'muss'::text,'muss'::text,'sollte'::text,'Küchenregel, Digga: Die Köchin muss die hohe Mütze tragen.'::text),
(302425,33603,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Правило кухні, бро: кухарка ... носити високий ковпак.'::text,'має'::text,'мусить'::text,'мала б'::text,'Правило кухні, бро: кухарка має носити високий ковпак.'::text),
(302424,33603,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Regla de la cocina, tío: la cocinera ... llevar el gorro alto.'::text,'tiene que'::text,'debe'::text,'debería'::text,'Regla de la cocina, tío: la cocinera tiene que llevar el gorro alto.'::text),
(302423,33603,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Règle de la cuisine, frérot : la cheffe ... porter la grande toque.'::text,'doit'::text,'doit'::text,'devrait'::text,'Règle de la cuisine, frérot : la cheffe doit porter la grande toque.'::text),
(302426,33603,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mutfak kuralı, kanka: aşçı uzun şapkayı ...'::text,'takmak zorunda'::text,'takmalı'::text,'takmalı'::text,'Mutfak kuralı, kanka: aşçı uzun şapkayı takmak zorunda.'::text),
(302427,33603,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Konyhai szabály, tesó: a szakácsnőnek ... hordania a magas sapkát.'::text,'kell'::text,'kell'::text,'kellene'::text,'Konyhai szabály, tesó: a szakácsnőnek kell hordania a magas sapkát.'::text),
(302430,33604,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Küchenziel: 50 Teller. Sie ... zuerst jede Soße probieren.'::text,'sollte'::text,'sollte'::text,'soll'::text,'Küchenziel: 50 Teller. Sie sollte zuerst jede Soße probieren.'::text),
(302434,33604,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ціль кухні: 50 тарілок. Вона ... спершу скуштувати кожен соус.'::text,'мала б'::text,'мала б'::text,'буде'::text,'Ціль кухні: 50 тарілок. Вона мала б спершу скуштувати кожен соус.'::text),
(302433,33604,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Objetivo de cocina: 50 platos. ... probar primero cada salsa.'::text,'Debería'::text,'Debería'::text,'Deberá'::text,'Objetivo de cocina: 50 platos. Debería probar primero cada salsa.'::text),
(302432,33604,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Objectif cuisine : 50 assiettes. Elle ... goûter chaque sauce d''abord.'::text,'devrait'::text,'devrait'::text,'devra'::text,'Objectif cuisine : 50 assiettes. Elle devrait goûter chaque sauce d''abord.'::text),
(302435,33604,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mutfak hedefi: 50 tabak. Önce her sosu ...'::text,'tatmalı'::text,'tatmalı'::text,'tadacak'::text,'Mutfak hedefi: 50 tabak. Önce her sosu tatmalı.'::text),
(302436,33604,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Konyhai cél: 50 tányér. Előbb minden szószt meg ... kóstolnia.'::text,'kellene'::text,'kellene'::text,'kell'::text,'Konyhai cél: 50 tányér. Előbb minden szószt meg kellene kóstolnia.'::text),
(302439,33605,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie kocht in der Küche, ... die Küche zum Kochen da ist.'::text,'weil'::text,'aber'::text,'also'::text,'Sie kocht in der Küche, weil die Küche zum Kochen da ist.'::text),
(302443,33605,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона готує на кухні, ... кухня для того, щоб готувати.'::text,'бо'::text,'але'::text,'тому'::text,'Вона готує на кухні, бо кухня для того, щоб готувати.'::text),
(302442,33605,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cocina en la cocina ... la cocina es para cocinar.'::text,'porque'::text,'pero'::text,'así que'::text,'Cocina en la cocina porque la cocina es para cocinar.'::text),
(302441,33605,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle cuisine dans la cuisine ... la cuisine, c''est pour cuisiner.'::text,'parce que'::text,'mais'::text,'donc'::text,'Elle cuisine dans la cuisine parce que la cuisine, c''est pour cuisiner.'::text),
(302444,33605,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mutfakta yemek yapıyor ... mutfak yemek yapmak içindir.'::text,'çünkü'::text,'ama'::text,'bu yüzden'::text,'Mutfakta yemek yapıyor çünkü mutfak yemek yapmak içindir.'::text),
(302445,33605,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A konyhában főz, ... a konyha főzésre való.'::text,'mert'::text,'de'::text,'ezért'::text,'A konyhában főz, mert a konyha főzésre való.'::text),
(313239,34805,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Teller ist fertig. Jetzt ... der Koch die Glocke läuten.'::text,'kann'::text,'kann'::text,'ist'::text,'Der Teller ist fertig. Jetzt kann der Koch die Glocke läuten.'::text),
(313243,34805,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тарілка готова. Тепер кухар ... подзвонити в дзвоник.'::text,'може'::text,'може'::text,'є'::text,'Тарілка готова. Тепер кухар може подзвонити в дзвоник.'::text),
(313242,34805,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El plato está listo. Ahora el cocinero ... tocar la campana.'::text,'puede'::text,'puede'::text,'está'::text,'El plato está listo. Ahora el cocinero puede tocar la campana.'::text),
(313241,34805,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''assiette est prête. Maintenant le cuisinier ... sonner la cloche.'::text,'peut'::text,'peut'::text,'est'::text,'L''assiette est prête. Maintenant le cuisinier peut sonner la cloche.'::text),
(313244,34805,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tabak hazır. Şimdi aşçı zili ...'::text,'çalabilir'::text,'çalabilir'::text,NULL::text,'Tabak hazır. Şimdi aşçı zili çalabilir.'::text),
(313245,34805,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A tányér kész. Most a szakács ... a csengőt.'::text,'megnyomhatja'::text,'megnyomhatja'::text,'van'::text,'A tányér kész. Most a szakács megnyomhatja a csengőt.'::text),
(313248,34806,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, ... läutet der Typ die Glocke? Weil die Pancakes fertig sind.'::text,'warum'::text,'wer'::text,'wo'::text,'Yo, warum läutet der Typ die Glocke? Weil die Pancakes fertig sind.'::text),
(313252,34806,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, ... цей тип дзвонить у дзвоник? Бо панкейки готові.'::text,'чому'::text,'хто'::text,'де'::text,'Йо, чому цей тип дзвонить у дзвоник? Бо панкейки готові.'::text),
(313251,34806,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tío, ¿... toca el colega la campana? Porque las tortitas están hechas.'::text,'por qué'::text,'quién'::text,'dónde'::text,'Tío, ¿por qué toca el colega la campana? Porque las tortitas están hechas.'::text),
(313250,34806,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wesh, ... le gars sonne la cloche ? Parce que les pancakes sont prêts.'::text,'pourquoi'::text,'qui'::text,'où'::text,'Wesh, pourquoi le gars sonne la cloche ? Parce que les pancakes sont prêts.'::text),
(313253,34806,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bizimki zili ... çalıyor? Çünkü pankekler hazır.'::text,'neden'::text,'kim'::text,'nerede'::text,'Kanka, bizimki zili neden çalıyor? Çünkü pankekler hazır.'::text),
