(313257,34807,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Typ ... die Glocke so heftig, irgendwie ikonisch.'::text,'läutete'::text,'läutete'::text,'läutete'::text,'Der Typ läutete die Glocke so heftig, irgendwie ikonisch.'::text),
