(313260,34807,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El colega ... la campana tan fuerte, bastante icónico.'::text,'tocó'::text,'tocó'::text,'tocó'::text,'El colega tocó la campana tan fuerte, bastante icónico.'::text),
(313259,34807,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le gars ... la cloche tellement fort, plutôt iconique.'::text,'a sonné'::text,'a sonné'::text,'a sonné'::text,'Le gars a sonné la cloche tellement fort, plutôt iconique.'::text),
