(313263,34807,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A srác olyan erősen ... a csengőt, elég ikonikus.'::text,'megnyomta'::text,'megnyomta'::text,'megnyomta'::text,'A srác olyan erősen megnyomta a csengőt, elég ikonikus.'::text),
(313266,34808,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestellung 12 fertig, im Zeitplan. „Ich ... die Glocke läuten“, beschließt er.'::text,'werde'::text,'werde'::text,NULL::text,'Bestellung 12 fertig, im Zeitplan. „Ich werde die Glocke läuten“, beschließt er.'::text),
(313270,34808,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Замовлення 12 готове, вчасно. «Я ... в дзвоник», — вирішує він.'::text,'подзвоню'::text,'збираюся подзвонити'::text,NULL::text,'Замовлення 12 готове, вчасно. «Я подзвоню в дзвоник», — вирішує він.'::text),
(313269,34808,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pedido 12 listo, en plazo. «... la campana», decide.'::text,'Tocaré'::text,'Voy a tocar'::text,NULL::text,'Pedido 12 listo, en plazo. «Tocaré la campana», decide.'::text),
(313268,34808,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Commande 12 terminée, dans les délais. « Je ... la cloche », décide-t-il.'::text,'sonnerai'::text,'vais sonner'::text,NULL::text,'Commande 12 terminée, dans les délais. « Je sonnerai la cloche », décide-t-il.'::text),
